/* ---------------- PHOTOS (Supabase Storage, bucket "photos") ---------------- */
// CONFIRMÉ par test réel : le plantage mémoire vient bien de createImageBitmap/canvas eux-mêmes sur
// ce téléphone précis (probablement un bug ou une limite du décodage accéléré GPU de ce navigateur),
// pas de canvas.toDataURL() spécifiquement comme on le pensait à l'étape précédente. La version qui
// a fonctionné sans plantage est celle qui n'utilise AUCUNE de ces API : on envoie le fichier original
// tel quel et on génère un aperçu ultra-léger avec URL.createObjectURL (aucun décodage de pixels par
// notre code — seul le navigateur décode, au moment de l'affichage, de façon optimisée en interne).
// Contrepartie : les photos ne sont plus compressées avant l'envoi (fichiers plus lourds, upload un
// peu plus lent), mais c'est nettement préférable à un plantage qui perd les données de la personne.
//
// GARDE-FOU SUPPLÉMENTAIRE (comme la plupart des grandes apps — WhatsApp, Instagram, etc.) : on refuse
// carrément les photos trop volumineuses AVANT de tenter quoi que ce soit avec elles, plutôt que de
// risquer un plantage. Le seuil est plus bas si l'appareil signale peu de mémoire disponible
// (navigator.deviceMemory, seulement disponible sur Chrome/Android). On ne peut jamais garantir à 100 %
// qu'Android ne tuera pas la page par manque de mémoire — mais on élimine ainsi la cause la plus fréquente.
async function resizeImageForUpload(file, maxDim = 640, quality = 0.75) {
  if (!file || !file.type?.startsWith("image/")) return { dataUrl: null, file, tooLarge: false };

  const deviceMemoryGB = (typeof navigator !== "undefined" && navigator.deviceMemory) || null;
  const maxBytes = deviceMemoryGB && deviceMemoryGB <= 2 ? 6 * 1024 * 1024 : 14 * 1024 * 1024;
  if (file.size > maxBytes) {
    return { dataUrl: null, file: null, tooLarge: true };
  }

  try {
    return { dataUrl: URL.createObjectURL(file), file, tooLarge: false };
  } catch (e) {
    return { dataUrl: null, file, tooLarge: false };
  }
}

async function supabaseUploadPhoto(file, userId, accessToken) {
  const ext = (file.name.split(".").pop() || "jpg").toLowerCase();
  const path = `${userId}/${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${ext}`;
  const res = await fetch(`${SUPABASE_URL}/storage/v1/object/photos/${path}`, {
    method: "POST",
    headers: {
      apikey: SUPABASE_KEY, Authorization: `Bearer ${accessToken}`,
      "Content-Type": file.type || "application/octet-stream",
    },
    body: file,
  });
  if (!res.ok) {
    const errText = await res.text().catch(() => "");
    throw new Error(`Impossible de téléverser la photo (${res.status}: ${errText || "réponse vide"})`);
  }
  return `${SUPABASE_URL}/storage/v1/object/public/photos/${path}`;
}

// Stocke la session localement pour rester connecté d'une visite à l'autre.
function saveLocalSession(session) {
  try { localStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify(session)); } catch (e) { /* stockage indisponible */ }
}
function loadLocalSession() {
  try {
    const raw = localStorage.getItem(SESSION_STORAGE_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch (e) { return null; }
}
function clearLocalSession() {
  try { localStorage.removeItem(SESSION_STORAGE_KEY); } catch (e) { /* rien à faire */ }
}

// Envoie un courriel transactionnel via la fonction serverless /api/send-email (qui relaie vers
// Resend en gardant la vraie clé API côté serveur — voir api/send-email.js).
async function sendAppEmail(to, subject, html) {
  const res = await fetch("/api/send-email", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ to, subject, html }),
  });
  if (!res.ok) {
    const data = await res.json().catch(() => ({}));
    throw new Error(data?.error || "Échec de l'envoi du courriel.");
  }
  return true;
}

async function sendPersonalizedMenuEmail(email, menuText, lang) {
  const subject = lang === "fr" ? "Votre menu personnalisé Me My Baby 🍽️" : lang === "es" ? "Tu menú personalizado de Me My Baby 🍽️" : "Your personalized Me My Baby menu 🍽️";
  const signoff = lang === "fr" ? "Bon appétit !" : lang === "es" ? "¡Buen provecho!" : "Enjoy your meals!";
  const html = `<div style="font-family:Georgia,serif;color:#3A3833;max-width:520px;margin:0 auto;line-height:1.6;white-space:pre-wrap;">
    ${menuText.replace(/\n/g, "<br>")}
    <p style="margin-top:24px;">${signoff}<br>— Léa</p>
  </div>`;
  return sendAppEmail(email, subject, html);
}

// Courriel combiné bienvenue + reçu, envoyé une seule fois au moment où la personne devient membre
// (plutôt que deux courriels distincts qui arriveraient coup sur coup pour le même évènement).
async function sendWelcomeReceiptEmail(email, { firstName, lang, billingCycle, priceDisplay, trialEndDate }) {
  const isAnnual = billingCycle === "annual";
  const T2 = {
    fr: {
      subject: "Bienvenue chez Me My Baby ! 🎉",
      greet: (n) => `Bienvenue${n ? " " + n : ""} !`,
      intro: "Votre abonnement Me My Baby est maintenant actif. Voici un aperçu de tout ce que vous venez de débloquer, et le reçu de votre commande.",
      whatsIncluded: "Ce qui est inclus",
      included: ["Léa, votre diététicienne virtuelle, pour des menus personnalisés chaque semaine", "Mia, votre assistante virtuelle, disponible à toute heure", "Le suivi complet de la grossesse et du développement de l'enfant jusqu'à 5 ans", "La communauté de parents"],
      receiptTitle: "Reçu",
      plan: isAnnual ? "Forfait annuel" : "Forfait mensuel",
      priceLine: `${priceDisplay} ${isAnnual ? "/ an" : "/ mois"}`,
      trialLine: `Premier paiement le ${trialEndDate}, à la fin de votre essai gratuit.`,
      cta: "Explorer l'application",
      signoff: "On est vraiment contentes de vous compter parmi nous 💛",
    },
    es: {
      subject: "¡Bienvenida a Me My Baby! 🎉",
      greet: (n) => `¡Bienvenida${n ? " " + n : ""}!`,
      intro: "Tu suscripción a Me My Baby ya está activa. Aquí tienes un resumen de todo lo que acabas de desbloquear, y el recibo de tu pedido.",
      whatsIncluded: "Qué incluye",
      included: ["Léa, tu nutricionista virtual, con menús personalizados cada semana", "Mia, tu asistente virtual, disponible a cualquier hora", "El seguimiento completo del embarazo y el desarrollo infantil hasta los 5 años", "La comunidad de padres"],
      receiptTitle: "Recibo",
      plan: isAnnual ? "Plan anual" : "Plan mensual",
      priceLine: `${priceDisplay} ${isAnnual ? "/ año" : "/ mes"}`,
      trialLine: `Primer pago el ${trialEndDate}, al final de tu prueba gratuita.`,
      cta: "Explorar la aplicación",
      signoff: "Estamos muy felices de tenerte con nosotras 💛",
    },
    en: {
      subject: "Welcome to Me My Baby! 🎉",
      greet: (n) => `Welcome${n ? " " + n : ""}!`,
      intro: "Your Me My Baby subscription is now active. Here's a recap of everything you just unlocked, along with your order receipt.",
      whatsIncluded: "What's included",
      included: ["Léa, your virtual dietitian, with personalized menus every week", "Mia, your virtual assistant, available any time", "Full pregnancy and child development tracking up to age 5", "The parent community"],
      receiptTitle: "Receipt",
      plan: isAnnual ? "Annual plan" : "Monthly plan",
      priceLine: `${priceDisplay} ${isAnnual ? "/ year" : "/ month"}`,
      trialLine: `First payment on ${trialEndDate}, at the end of your free trial.`,
      cta: "Explore the app",
      signoff: "We're so glad to have you with us 💛",
    },
  }[lang] || {};

  const html = `<div style="font-family:Georgia,serif;color:#3A3833;max-width:480px;margin:0 auto;line-height:1.6;">
    <h2 style="color:#2F4858;">${T2.greet(firstName)}</h2>
    <p>${T2.intro}</p>
    <div style="background:#FBF6ED;border-radius:14px;padding:16px 18px;margin:20px 0;">
      <p style="margin:0 0 10px;font-weight:700;color:#2F4858;">${T2.whatsIncluded}</p>
      <ul style="margin:0;padding-left:18px;">${T2.included.map((i) => `<li style="margin-bottom:6px;">${i}</li>`).join("")}</ul>
    </div>
    <div style="border:1px solid #E7E1D3;border-radius:14px;padding:16px 18px;margin:20px 0;">
      <p style="margin:0 0 4px;font-size:12px;text-transform:uppercase;letter-spacing:0.06em;color:#7A7364;font-weight:700;">${T2.receiptTitle}</p>
      <p style="margin:0 0 4px;font-weight:700;color:#2F4858;">Me My Baby — ${T2.plan}</p>
      <p style="margin:0 0 8px;">${T2.priceLine}</p>
      <p style="margin:0;font-size:13px;color:#7A7364;">${T2.trialLine}</p>
    </div>
    <div style="text-align:center;margin:24px 0;">
      <a href="https://me-my-baby.vercel.app" style="background:#D4A54A;color:#fff;text-decoration:none;padding:12px 26px;border-radius:999px;font-weight:700;display:inline-block;">${T2.cta}</a>
    </div>
    <p>${T2.signoff}</p>
  </div>`;

  return sendAppEmail(email, T2.subject, html);
}

// Courriel envoyé quand un paiement échoue et que le compte est bloqué — invite la personne à
// mettre à jour son mode de paiement pour retrouver l'accès.
async function sendPaymentFailedEmail(email, { firstName, lang }) {
  const T3 = {
    fr: {
      subject: "Problème avec votre paiement Me My Baby",
      greet: (n) => `Bonjour${n ? " " + n : ""},`,
      body: "Nous n'avons pas pu traiter votre dernier paiement pour votre abonnement Me My Baby. Votre accès est temporairement suspendu jusqu'à ce que le mode de paiement soit mis à jour.",
      cta: "Mettre à jour mon paiement",
      note: "Une fois le paiement mis à jour, votre accès sera immédiatement rétabli.",
    },
    es: {
      subject: "Problema con tu pago de Me My Baby",
      greet: (n) => `Hola${n ? " " + n : ""},`,
      body: "No pudimos procesar tu último pago de la suscripción a Me My Baby. Tu acceso está temporalmente suspendido hasta que se actualice el método de pago.",
      cta: "Actualizar mi pago",
      note: "Una vez actualizado el pago, tu acceso se restablecerá de inmediato.",
    },
    en: {
      subject: "Issue with your Me My Baby payment",
      greet: (n) => `Hi${n ? " " + n : ""},`,
      body: "We weren't able to process your latest payment for your Me My Baby subscription. Your access is temporarily on hold until your payment method is updated.",
      cta: "Update my payment",
      note: "Once your payment is updated, your access will be restored right away.",
    },
  }[lang] || {};

  const html = `<div style="font-family:Georgia,serif;color:#3A3833;max-width:480px;margin:0 auto;line-height:1.6;">
    <h2 style="color:#B3261E;">${T3.greet(firstName)}</h2>
    <p>${T3.body}</p>
    <div style="text-align:center;margin:24px 0;">
      <a href="https://me-my-baby.vercel.app" style="background:#B3261E;color:#fff;text-decoration:none;padding:12px 26px;border-radius:999px;font-weight:700;display:inline-block;">${T3.cta}</a>
    </div>
    <p style="font-size:13px;color:#7A7364;">${T3.note}</p>
  </div>`;

  return sendAppEmail(email, T3.subject, html);
}



