/* ---------------- PROFILE ---------------- */
// Champ de date flexible : garde le calendrier habituel, mais ajoute une saisie manuelle rapide au
// format AAAA-MM-JJ à côté — plus rapide que de faire défiler un calendrier pour une date de naissance
// ancienne. Les deux champs restent synchronisés entre eux.
function FlexibleDateInput({ value, onChange, style }) {
  const [textValue, setTextValue] = useState(value || "");
  const dateInputRef = useRef(null);
  useEffect(() => { setTextValue(value || ""); }, [value]);

  const handleTextChange = (e) => {
    const v = e.target.value;
    setTextValue(v);
    if (/^\d{4}-\d{2}-\d{2}$/.test(v)) {
      const d = new Date(v + "T00:00:00");
      if (!isNaN(d.getTime())) onChange(v);
    }
  };

  const openPicker = () => {
    const el = dateInputRef.current;
    if (!el) return;
    if (typeof el.showPicker === "function") {
      try { el.showPicker(); } catch (e) { el.focus(); }
    } else {
      el.focus();
    }
  };

  return (
    <div style={{ position: "relative", width: "100%" }}>
      <input
        type="text" inputMode="numeric" placeholder="AAAA-MM-JJ" value={textValue}
        onChange={handleTextChange} maxLength={10}
        style={{ ...style, width: "100%", boxSizing: "border-box", paddingRight: 38 }}
      />
      <button
        type="button" onClick={openPicker} aria-label="Ouvrir le calendrier"
        style={{
          position: "absolute", right: 8, top: "50%", transform: "translateY(-50%)",
          background: "none", border: "none", cursor: "pointer", padding: 4,
          display: "flex", alignItems: "center", color: COLORS.muted,
        }}
      >
        <Calendar size={17} />
      </button>
      {/* Champ natif invisible, utilisé uniquement pour afficher le calendrier via showPicker() */}
      <input
        ref={dateInputRef} type="date" value={value || ""} onChange={(e) => onChange(e.target.value)}
        tabIndex={-1} aria-hidden="true"
        style={{ position: "absolute", left: 0, top: 0, width: 1, height: 1, opacity: 0, border: "none", padding: 0 }}
      />
    </div>
  );
}

function ProfileSection({ lang, setLang, children, setChildren, userProfile, onLogout, session, justSignedUp, onOnboardingDone, standalone, isMember, onBecomeMember, goTo }) {
  const [editing, setEditing] = useState(!!justSignedUp);
  const [saved, setSaved] = useState(false);
  const [saving, setSaving] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [changingPassword, setChangingPassword] = useState(false);
  const [showPasswordFields, setShowPasswordFields] = useState(false);
  const [showNewPassword, setShowNewPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [passwordMsg, setPasswordMsg] = useState("");
  const [photo, setPhoto] = useState(userProfile?.photoUrl || null);
  const [photoFile, setPhotoFile] = useState(null);
  const [photoUploaded, setPhotoUploaded] = useState(!!userProfile?.photoUrl);
  const [profilePhotoWarning, setProfilePhotoWarning] = useState("");
  const [childPhotoWarning, setChildPhotoWarning] = useState("");
  const [upcomingPhotoWarning, setUpcomingPhotoWarning] = useState("");
  const photoInputRef = useRef(null);
  const hasSession = !!(session?.access_token && session?.user?.id);
  const [form, setForm] = useState({
    name: userProfile ? `${userProfile.firstName || ""} ${userProfile.lastName || ""}`.trim() || (lang === "fr" ? "Prénom Nom" : lang === "es" ? "Nombre Apellido" : "First Last") : (lang === "fr" ? "Prénom Nom" : lang === "es" ? "Nombre Apellido" : "First Last"),
    email: userProfile?.email || "vous@exemple.com",
    username: userProfile?.username || "",
    country: userProfile?.country || "CA",
    language: userProfile?.language || lang || "fr",
    age: userProfile?.motherAge || "",
    birthdate: userProfile?.motherBirthdate || "",
    children: userProfile?.children ?? "0",
    dueDate: userProfile?.dueDate || "",
    preferredCurrency: userProfile?.preferredCurrency || "",
    pregnancyProfile: userProfile?.pregnancyProfile || [],
  });
  // Fiche du prochain enfant à ajouter — un seul à la fois en mémoire, peu importe le nombre total
  // d'enfants de la personne (1 ou 20) : chaque enfant est envoyé et sauvegardé immédiatement,
  // puis cette fiche est vidée avant de pouvoir en ajouter un autre.
  const [childDraft, setChildDraft] = useState({ name: "", birthdate: "", photo: null, photoFile: null, photoUploaded: false });
  // Champ facultatif : tant que la personne n'y a pas indiqué un nombre, la carte d'ajout d'enfant
  // reste cachée — plusieurs personnes n'ont pas encore d'enfant né et ne veulent pas voir ce champ.
  const [expectedChildrenCount, setExpectedChildrenCount] = useState("");
  const [childrenToRemove, setChildrenToRemove] = useState([]);
  const [removingChildren, setRemovingChildren] = useState(false);
  const [removeChildrenError, setRemoveChildrenError] = useState("");
  const [addingChild, setAddingChild] = useState(false);
  const [childAddError, setChildAddError] = useState("");
  // Fiche spéciale pour un enfant à naître, basée sur la date prévue d'accouchement — sa date de naissance
  // sera la DPA tant qu'elle n'est pas modifiée manuellement (par exemple une fois bébé né).
  const [upcomingChild, setUpcomingChild] = useState({ name: "", birthdate: "", photo: null, photoFile: null, photoUploaded: false, birthdateTouched: false });
  const [addingUpcoming, setAddingUpcoming] = useState(false);
  const [upcomingAddError, setUpcomingAddError] = useState("");
  const [upcomingJustAdded, setUpcomingJustAdded] = useState(false);

  const updateUpcomingChild = (field, value) => {
    setUpcomingChild((u) => ({ ...u, [field]: value, ...(field === "birthdate" ? { birthdateTouched: true } : {}) }));
  };
  const handleUpcomingChildPhoto = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const { dataUrl, file: resizedFile, tooLarge } = await resizeImageForUpload(file);
    if (tooLarge) { setUpcomingPhotoWarning(L.photoTooLarge); e.target.value = ""; return; }
    setUpcomingPhotoWarning("");
    setUpcomingChild((u) => ({ ...u, ...(dataUrl ? { photo: dataUrl } : {}), photoFile: resizedFile }));
    if (hasSession) {
      try {
        const url = await supabaseUploadPhoto(resizedFile, session.user.id, session.access_token);
        // On libère la référence mémoire locale (blob) dès que la version distante est disponible —
        // sans ça, chaque photo prise (profil, enfant 1, enfant 2, ... enfant 10) reste en mémoire
        // en plus des suivantes, et finit par saturer la mémoire du téléphone.
        if (dataUrl && dataUrl.startsWith("blob:")) URL.revokeObjectURL(dataUrl);
        setUpcomingChild((u) => ({ ...u, photo: url, photoFile: null, photoUploaded: true }));
      } catch (e) { /* on retentera au moment d'ajouter — on garde le blob local en cas d'échec */ }
    }
  };
  // Quand la date prévue d'accouchement change, on répercute automatiquement sur l'enfant "à venir" :
  // - s'il n'a pas encore été ajouté (juste un brouillon), on met sa date à jour comme avant;
  // - s'il a DÉJÀ été ajouté (dans "children", identifié par une date de naissance future), on met à
  //   jour sa fiche existante — ou on la supprime si la date prévue d'accouchement est effacée.
  const handleDueDateChange = async (dd) => {
    setForm((f) => ({ ...f, dueDate: dd }));
    setUpcomingChild((u) => (u.birthdateTouched ? u : { ...u, birthdate: dd }));

    const existingUpcoming = children.find((c) => c.birthdate && new Date(c.birthdate) > new Date());
    if (!existingUpcoming) return;

    if (!dd) {
      // Date effacée : on retire l'enfant "à venir" déjà ajouté.
      try {
        if (hasSession && typeof existingUpcoming.id === "string" && !existingUpcoming.id.startsWith("local-")) {
          await supabaseDeleteChild(existingUpcoming.id, session.access_token);
        }
        setChildren((c) => c.filter((ch) => ch.id !== existingUpcoming.id));
      } catch (e) { /* si la suppression échoue, l'enfant reste visible — pas de perte de données */ }
    } else {
      // Nouvelle date : on met à jour la date de naissance de l'enfant "à venir" déjà ajouté.
      try {
        if (hasSession && typeof existingUpcoming.id === "string" && !existingUpcoming.id.startsWith("local-")) {
          const row = await supabaseUpdateChild(existingUpcoming.id, { birthdate: dd }, session.access_token);
          setChildren((c) => c.map((ch) => (ch.id === existingUpcoming.id ? mapChildRow(row) : ch)));
        } else {
          setChildren((c) => c.map((ch) => (ch.id === existingUpcoming.id ? { ...ch, birthdate: dd } : ch)));
        }
      } catch (e) { /* on garde l'ancienne date affichée si la mise à jour échoue */ }
    }
  };

  const addUpcomingChildNow = async () => {
    setAddingUpcoming(true);
    setUpcomingAddError("");
    const birthdate = upcomingChild.birthdate || form.dueDate || "";
    try {
      if (hasSession) {
        let photoUrl = upcomingChild.photoUploaded ? upcomingChild.photo : null;
        if (!photoUrl && upcomingChild.photoFile) photoUrl = await supabaseUploadPhoto(upcomingChild.photoFile, session.user.id, session.access_token);
        const row = await supabaseAddChild({ name: upcomingChild.name.trim() || L.upcomingBadge, birthdate, photo: photoUrl }, session.user.id, session.access_token);
        setChildren((c) => [...c, mapChildRow(row)]);
      } else {
        setChildren((c) => [...c, { name: upcomingChild.name.trim() || L.upcomingBadge, birthdate, photo: upcomingChild.photo, id: `local-${Date.now()}-${Math.random()}` }]);
      }
      setUpcomingChild({ name: "", birthdate: "", photo: null, photoFile: null, photoUploaded: false, birthdateTouched: false }); // libère la mémoire tout de suite
      setUpcomingJustAdded(true);
    } catch (e) {
      setUpcomingAddError(L.errorSave);
    }
    setAddingUpcoming(false);
  };

  const updateChildDraftField = (field, value) => setChildDraft((d) => ({ ...d, [field]: value }));
  const handleChildDraftPhoto = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const { dataUrl, file: resizedFile, tooLarge } = await resizeImageForUpload(file);
    if (tooLarge) { setChildPhotoWarning(L.photoTooLarge); e.target.value = ""; return; }
    setChildPhotoWarning("");
    setChildDraft((d) => ({ ...d, ...(dataUrl ? { photo: dataUrl } : {}), photoFile: resizedFile }));
    if (hasSession) {
      try {
        const url = await supabaseUploadPhoto(resizedFile, session.user.id, session.access_token);
        // Libère la référence mémoire locale dès l'envoi réussi (voir note plus haut) — essentiel pour
        // qu'une famille de 10 enfants n'accumule pas 10 photos non compressées en mémoire d'un coup.
        if (dataUrl && dataUrl.startsWith("blob:")) URL.revokeObjectURL(dataUrl);
        setChildDraft((d) => ({ ...d, photo: url, photoFile: null, photoUploaded: true }));
      } catch (e) { /* échec d'envoi : on retente au moment d'ajouter, avec le fichier gardé en mémoire */ }
    }
  };
  const addChildNow = async () => {
    if (!childDraft.name.trim()) return;
    setAddingChild(true);
    setChildAddError("");
    const birthdate = childDraft.birthdate || "";
    try {
      if (hasSession) {
        let photoUrl = childDraft.photoUploaded ? childDraft.photo : null; // déjà envoyée immédiatement lors de la sélection
        if (!photoUrl && childDraft.photoFile) photoUrl = await supabaseUploadPhoto(childDraft.photoFile, session.user.id, session.access_token);
        const row = await supabaseAddChild({ name: childDraft.name.trim(), birthdate, photo: photoUrl }, session.user.id, session.access_token);
        setChildren((c) => [...c, mapChildRow(row)]);
      } else {
        setChildren((c) => [...c, { name: childDraft.name.trim(), birthdate, photo: childDraft.photo, id: `local-${Date.now()}-${Math.random()}` }]);
      }
      // On vide complètement la fiche avant d'en permettre une nouvelle : un seul enfant à la fois
      // en mémoire, donc la taille de la famille (1 ou 20 enfants) n'a aucun impact sur la stabilité.
      setChildDraft({ name: "", birthdate: "", photo: null, photoFile: null, photoUploaded: false });
      setChildPhotoWarning("");
    } catch (e) {
      // On affiche le détail technique de l'erreur pour pouvoir enfin identifier la vraie cause
      // (permissions Supabase, réseau, etc.) plutôt qu'un message générique qui ne dit rien.
      setChildAddError(`${L.errorSave} [${(e && e.message) ? e.message : String(e)}]`);
    }
    setAddingChild(false);
  };

  // Retire les enfants cochés (déclenché quand la personne diminue "Nombre d'enfants actuel" en dessous
  // du nombre d'enfants déjà enregistrés) et ajuste le compteur en conséquence une fois terminé.
  const confirmRemoveChildren = async () => {
    if (childrenToRemove.length === 0) return;
    setRemovingChildren(true);
    setRemoveChildrenError("");
    try {
      for (const id of childrenToRemove) {
        if (hasSession && typeof id === "string" && !id.startsWith("local-")) {
          await supabaseDeleteChild(id, session.access_token);
        }
      }
      setChildren((c) => c.filter((ch) => !childrenToRemove.includes(ch.id)));
      const remainingBornCount = children.filter((c) => (!c.birthdate || new Date(c.birthdate) <= new Date()) && !childrenToRemove.includes(c.id)).length;
      setExpectedChildrenCount(String(remainingBornCount));
      setChildrenToRemove([]);
    } catch (e) {
      setRemoveChildrenError(L.errorSave);
    }
    setRemovingChildren(false);
  };

  const handlePhotoChange = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const { dataUrl, file: resizedFile, tooLarge } = await resizeImageForUpload(file);
    if (tooLarge) { setProfilePhotoWarning(L.photoTooLarge); e.target.value = ""; return; }
    setProfilePhotoWarning("");
    if (dataUrl) setPhoto(dataUrl);
    setPhotoFile(resizedFile);
    if (hasSession) {
      try {
        const url = await supabaseUploadPhoto(resizedFile, session.user.id, session.access_token);
        // Photo de profil principale : même libération immédiate — c'est souvent la toute première
        // photo prise dans le formulaire, donc la corriger ici évite déjà une bonne partie de l'accumulation.
        if (dataUrl && dataUrl.startsWith("blob:")) URL.revokeObjectURL(dataUrl);
        setPhoto(url);
        setPhotoFile(null);
        setPhotoUploaded(true);
      } catch (e) { /* échec d'envoi : on retente au moment d'Enregistrer */ }
    }
  };

  const computeBirthdateFromAge = (value, unit) => {
    const n = Number(value) || 0;
    const d = new Date();
    if (unit === "months") d.setMonth(d.getMonth() - n);
    else d.setFullYear(d.getFullYear() - n);
    return d.toISOString().slice(0, 10);
  };

  // Calcule un âge (en années, ou en mois si moins de 2 ans) à partir d'une date de naissance
  const computeAgeFromBirthdate = (birthdateStr) => {
    if (!birthdateStr) return null;
    const birth = new Date(birthdateStr + "T00:00:00");
    if (isNaN(birth.getTime())) return null;
    const today = new Date();
    let years = today.getFullYear() - birth.getFullYear();
    const monthDiff = today.getMonth() - birth.getMonth();
    if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < birth.getDate())) years--;
    if (years < 2) {
      let months = (today.getFullYear() - birth.getFullYear()) * 12 + (today.getMonth() - birth.getMonth());
      if (today.getDate() < birth.getDate()) months--;
      return { value: Math.max(0, months), unit: "months" };
    }
    return { value: Math.max(0, years), unit: "years" };
  };

  const handleSave = async () => {
    setSaving(true);
    setErrorMsg("");
    let hadError = false;
    let errorDetail = "";
    // 0. Sauvegarde de la photo de profil (si une nouvelle a été choisie)
    let profilePhotoUrl = photo;
    if (hasSession && photoFile) {
      try {
        profilePhotoUrl = await supabaseUploadPhoto(photoFile, session.user.id, session.access_token);
      } catch (e) { hadError = true; errorDetail = e?.message || String(e); }
    }
    // 1. Sauvegarde nom / courriel / âge / pays / langue du profil
    // (les enfants sont ajoutés séparément, un à la fois, via leur propre bouton "Ajouter" — voir addChildNow / addUpcomingChildNow —
    // ce qui évite de garder plusieurs photos d'enfants en mémoire en même temps, peu importe la taille de la famille.)
    if (hasSession && !hadError) {
      const [firstName, ...rest] = form.name.trim().split(" ");
      try {
        await supabaseUpdateProfile(session.user.id, {
          first_name: firstName || "", last_name: rest.join(" "), mother_age: form.age || null, mother_birthdate: form.birthdate || null,
          due_date: form.dueDate || null,
          children: String(children.filter((c) => !c.birthdate || new Date(c.birthdate) <= new Date()).length),
          pregnancy_profile: form.pregnancyProfile || [],
          preferred_currency: form.preferredCurrency || null,
          country: form.country || null, language: form.language || "fr", photo_url: profilePhotoUrl || null,
        }, session.access_token);
      } catch (e) { hadError = true; errorDetail = e?.message || String(e); }
    }
    if (form.language && form.language !== lang && setLang) setLang(form.language); // applique la nouvelle langue immédiatement

    setSaving(false);
    if (hadError) {
      setErrorMsg(`${L.errorSave} [${errorDetail}]`);
      return; // on reste sur le formulaire d'édition, rien n'est perdu, la personne peut réessayer
    }
    setPhoto(profilePhotoUrl);
    setEditing(false);
    setSaved(true);
    if (onOnboardingDone) onOnboardingDone();
  };

  const handleChangePassword = async () => {
    setPasswordMsg("");
    if (newPassword.length < 8) { setPasswordMsg(L.passwordTooShort); return; }
    if (newPassword !== confirmPassword) { setPasswordMsg(L.passwordMismatch); return; }
    if (!hasSession) return;
    setChangingPassword(true);
    try {
      await supabaseUpdatePassword(newPassword, session.access_token);
      setPasswordMsg(L.passwordChanged);
      setNewPassword("");
      setConfirmPassword("");
    } catch (e) {
      setPasswordMsg(e?.message || L.passwordError);
    }
    setChangingPassword(false);
  };

  const L = lang === "fr"
    ? { title: "Mon profil", subtitle: "Vos informations personnelles.", name: "Nom complet", email: "Courriel",
        username: "Nom d'utilisateur (optionnel)", country: "Pays", language: "Langue de l'application",
        age: "Votre âge", birthdate: "Votre date de naissance", ageComputed: (a) => `Vous avez ${a} ans`,
        children: "Nombre d'enfants actuel", due: "Date prévue d'accouchement (si applicable)", edit: "Modifier", save: "Enregistrer",
        continueBtn: "Continuer vers mon profil",
        cancel: "Annuler", saved: "Profil mis à jour.", memberSince: "Membre depuis", demo: "Démonstration : aucune donnée n'est réellement sauvegardée.",
        errorSave: "Certaines informations n'ont pas pu être enregistrées (connexion instable). Rien n'a été perdu — vérifiez les champs ci-dessous et cliquez de nouveau sur Enregistrer.",
        congrats: "Félicitations pour votre grossesse ! 🎉", dueOn: (d) => `Bébé est attendu pour le ${d}`,
        weeksLabel: (w, d) => `Vous en êtes à ${w} semaine${w > 1 ? "s" : ""}${d > 0 ? ` et ${d} jour${d > 1 ? "s" : ""}` : ""}`,
        trimesterLabel: (t) => `${t}${t === 1 ? "er" : "e"} trimestre`,
        daysRemainingLabel: (n) => `${n} jour${n > 1 ? "s" : ""} restant${n > 1 ? "s" : ""}`, changePhoto: "Changer la photo", addPhoto: "Ajouter une photo",
        logout: "Se déconnecter",
        welcomeTitle: (name) => `Bonjour ${name} !`, welcomeSubtitle: "Débutons par créer votre profil.",
        childName: (i) => `Prénom de l'enfant ${i + 1}`, childBirthdate: "Date de naissance",
        childAgeComputed: (a, unit) => unit === "months" ? `${a} mois` : `${a} an${a > 1 ? "s" : ""}`,
        childPhoto: "Photo", saving: "Enregistrement…",
        currentChildrenCount: (n) => `vous avez actuellement ${n} enfant${n > 1 ? "s" : ""} enregistré${n > 1 ? "s" : ""}`,
        upcomingBadge: "À venir", upcomingNamePlaceholder: "Prénom (si déjà choisi)",
        upcomingDueNote: "Basée sur votre date prévue d'accouchement — modifiable une fois bébé né.", addChildBtn: "Ajouter cet enfant",
        pregnancyProfileLabel: "Sélectionnez un choix", pregnancyProfileStandard: "Grossesse standard",
        pregnancyProfile3540: "Grossesse 35 à 40 ans", pregnancyProfile40plus: "Grossesse 40 ans et plus",
        pregnancyProfileRisk: "Grossesse à risque avec certaines complications",
        changePassword: "Changer le mot de passe", newPassword: "Nouveau mot de passe", confirmPassword: "Confirmer le mot de passe",
        currentPasswordLabel: "Mot de passe actuel",
        incompleteFormName: "Entrez votre nom pour continuer.",
        incompleteFormChildren: (n) => `Ajoutez encore ${n} enfant${n > 1 ? "s" : ""} pour continuer (selon le nombre indiqué ci-dessus).`,
        currencyLabel: "Devise préférée", currencyAuto: (c) => `Automatique selon mon pays (${c})`,
        currencyCAD: "Dollar canadien (CAD)", currencyUSD: "Dollar américain (USD)", currencyEUR: "Euro (EUR)",
        updatePassword: "Mettre à jour le mot de passe", passwordTooShort: "Le mot de passe doit contenir au moins 8 caractères.",
        passwordMismatch: "Les deux mots de passe ne correspondent pas.", passwordChanged: "Mot de passe mis à jour avec succès.",
        passwordError: "Impossible de changer le mot de passe. Réessayez.",
        photoTooLarge: "📵 Cette photo est trop volumineuse pour votre appareil en ce moment (manque de mémoire possible). Vous pouvez continuer sans photo, ou réessayer avec une photo plus légère.",
        selectChildToRemove: (n) => n > 0 ? `Sélectionnez ${n} enfant${n > 1 ? "s" : ""} à retirer.` : "Sélectionnez le ou les enfants à retirer.",
        confirmRemove: "Confirmer le retrait" }
    : lang === "es"
    ? { title: "Mi perfil", subtitle: "Tu información personal.", name: "Nombre completo", email: "Correo electrónico",
        username: "Nombre de usuario (opcional)", country: "País", language: "Idioma de la aplicación",
        age: "Tu edad", birthdate: "Tu fecha de nacimiento", ageComputed: (a) => `Tienes ${a} años`,
        children: "Número actual de hijos", due: "Fecha probable de parto (si aplica)", edit: "Editar", save: "Guardar",
        continueBtn: "Continuar a mi perfil",
        cancel: "Cancelar", saved: "Perfil actualizado.", memberSince: "Miembro desde", demo: "Demostración: ningún dato se guarda realmente.",
        errorSave: "Algunos datos no se pudieron guardar (conexión inestable). No se perdió nada — revisa los campos abajo y haz clic en Guardar de nuevo.",
        congrats: "¡Felicidades por tu embarazo! 🎉", dueOn: (d) => `El bebé está previsto para el ${d}`,
        weeksLabel: (w, d) => `Estás en la semana ${w}${d > 0 ? ` y ${d} día${d > 1 ? "s" : ""}` : ""}`,
        trimesterLabel: (t) => `${t}º trimestre`,
        daysRemainingLabel: (n) => `${n} día${n > 1 ? "s" : ""} restante${n > 1 ? "s" : ""}`, changePhoto: "Cambiar la foto", addPhoto: "Agregar una foto",
        logout: "Cerrar sesión",
        welcomeTitle: (name) => `¡Hola ${name}!`, welcomeSubtitle: "Comencemos por crear tu perfil.",
        childName: (i) => `Nombre del hijo/a ${i + 1}`, childBirthdate: "Fecha de nacimiento",
        childAgeComputed: (a, unit) => unit === "months" ? `${a} meses` : `${a} año${a > 1 ? "s" : ""}`,
        childPhoto: "Foto", saving: "Guardando…",
        currentChildrenCount: (n) => `actualmente tienes ${n} hijo${n > 1 ? "s" : ""} registrado${n > 1 ? "s" : ""}`,
        upcomingBadge: "Por nacer", upcomingNamePlaceholder: "Nombre (si ya lo elegiste)",
        upcomingDueNote: "Basada en tu fecha probable de parto — se puede actualizar cuando nazca el bebé.", addChildBtn: "Agregar este hijo/a",
        pregnancyProfileLabel: "Selecciona una opción", pregnancyProfileStandard: "Embarazo estándar",
        pregnancyProfile3540: "Embarazo de 35 a 40 años", pregnancyProfile40plus: "Embarazo de 40 años o más",
        pregnancyProfileRisk: "Embarazo de riesgo con ciertas complicaciones",
        changePassword: "Cambiar la contraseña", newPassword: "Nueva contraseña", confirmPassword: "Confirmar contraseña",
        currentPasswordLabel: "Contraseña actual",
        incompleteFormName: "Ingresa tu nombre para continuar.",
        incompleteFormChildren: (n) => `Agrega ${n} hijo${n > 1 ? "s" : ""} más para continuar (según el número indicado arriba).`,
        currencyLabel: "Moneda preferida", currencyAuto: (c) => `Automática según mi país (${c})`,
        currencyCAD: "Dólar canadiense (CAD)", currencyUSD: "Dólar estadounidense (USD)", currencyEUR: "Euro (EUR)",
        updatePassword: "Actualizar contraseña", passwordTooShort: "La contraseña debe tener al menos 8 caracteres.",
        passwordMismatch: "Las dos contraseñas no coinciden.", passwordChanged: "Contraseña actualizada con éxito.",
        passwordError: "No se pudo cambiar la contraseña. Inténtalo de nuevo.",
        photoTooLarge: "📵 Esta foto es demasiado pesada para tu dispositivo en este momento (posible falta de memoria). Puedes continuar sin foto, o intentar con una foto más liviana.",
        selectChildToRemove: (n) => n > 0 ? `Selecciona ${n} hijo${n > 1 ? "s" : ""} para quitar.` : "Selecciona el hijo/a o los hijos a quitar.",
        confirmRemove: "Confirmar el retiro" }
    : { title: "My profile", subtitle: "Your personal information.", name: "Full name", email: "Email",
        username: "Username (optional)", country: "Country", language: "App language",
        age: "Your age", birthdate: "Your date of birth", ageComputed: (a) => `You are ${a} years old`,
        children: "Current number of children", due: "Expected due date (if applicable)", edit: "Edit", save: "Save",
        continueBtn: "Continue to my profile",
        cancel: "Cancel", saved: "Profile updated.", memberSince: "Member since", demo: "Demo only: no data is actually saved.",
        errorSave: "Some information couldn't be saved (unstable connection). Nothing was lost — check the fields below and click Save again.",
        congrats: "Congratulations on your pregnancy! 🎉", dueOn: (d) => `Baby is due on ${d}`,
        weeksLabel: (w, d) => `You're at ${w} week${w > 1 ? "s" : ""}${d > 0 ? ` and ${d} day${d > 1 ? "s" : ""}` : ""}`,
        trimesterLabel: (t) => `${t === 1 ? "1st" : t === 2 ? "2nd" : "3rd"} trimester`,
        daysRemainingLabel: (n) => `${n} day${n > 1 ? "s" : ""} to go`, changePhoto: "Change photo", addPhoto: "Add a photo",
        logout: "Log out",
        welcomeTitle: (name) => `Hello ${name}!`, welcomeSubtitle: "Let's start by creating your profile.",
        childName: (i) => `Child ${i + 1}'s first name`, childBirthdate: "Date of birth",
        childAgeComputed: (a, unit) => unit === "months" ? `${a} month${a > 1 ? "s" : ""}` : `${a} year${a > 1 ? "s" : ""}`,
        childPhoto: "Photo", saving: "Saving…",
        currentChildrenCount: (n) => `you currently have ${n} registered child${n > 1 ? "ren" : ""}`,
        upcomingBadge: "Upcoming", upcomingNamePlaceholder: "First name (if already chosen)",
        upcomingDueNote: "Based on your expected due date — you can update this once baby is born.", addChildBtn: "Add this child",
        pregnancyProfileLabel: "Select one option", pregnancyProfileStandard: "Standard pregnancy",
        pregnancyProfile3540: "Pregnancy 35 to 40", pregnancyProfile40plus: "Pregnancy 40 and older",
        pregnancyProfileRisk: "High-risk pregnancy with certain complications",
        changePassword: "Change password", newPassword: "New password", confirmPassword: "Confirm password",
        currentPasswordLabel: "Current password",
        incompleteFormName: "Enter your name to continue.",
        incompleteFormChildren: (n) => `Add ${n} more child${n > 1 ? "ren" : ""} to continue (based on the number entered above).`,
        currencyLabel: "Preferred currency", currencyAuto: (c) => `Automatic based on my country (${c})`,
        currencyCAD: "Canadian dollar (CAD)", currencyUSD: "US dollar (USD)", currencyEUR: "Euro (EUR)",
        updatePassword: "Update password", passwordTooShort: "Password must be at least 8 characters.",
        passwordMismatch: "The two passwords don't match.", passwordChanged: "Password updated successfully.",
        passwordError: "Couldn't change the password. Please try again.",
        photoTooLarge: "📵 This photo is too large for your device right now (possible low memory). You can continue without a photo, or try again with a lighter photo.",
        selectChildToRemove: (n) => n > 0 ? `Select ${n} child${n > 1 ? "ren" : ""} to remove.` : "Select the child/children to remove.",
        confirmRemove: "Confirm removal" };

  const inputStyle = { width: "100%", padding: "10px 13px", borderRadius: 10, border: `1px solid ${COLORS.line}`, fontSize: 14.5, boxSizing: "border-box" };
  const labelStyle = { display: "flex", flexDirection: "column", gap: 6, fontSize: 13.5, color: COLORS.muted, fontWeight: 600, marginBottom: 14 };
  const initials = form.name.split(" ").map((s) => s[0]).join("").slice(0, 2).toUpperCase();

  const pregnancy = useMemo(() => {
    if (!form.dueDate) return null;
    const dueDateObj = new Date(form.dueDate + "T00:00:00");
    if (isNaN(dueDateObj.getTime())) return null;
    const conceptionStart = new Date(dueDateObj);
    conceptionStart.setDate(conceptionStart.getDate() - 280); // 40 semaines avant la DPA
    const today = new Date();
    const diffDays = Math.floor((today - conceptionStart) / 86400000);
    const weeks = Math.max(0, Math.min(42, Math.floor(diffDays / 7)));
    const days = Math.max(0, diffDays % 7);
    const trimester = weeks <= 13 ? 1 : weeks <= 27 ? 2 : 3;
    const fmtDue = dueDateObj.toLocaleDateString(lang === "fr" ? "fr-CA" : lang === "es" ? "es-MX" : "en-CA", { day: "numeric", month: "long", year: "numeric" });
    const daysRemaining = Math.max(0, Math.ceil((dueDateObj - new Date(new Date().toDateString())) / 86400000));
    return { weeks, days, trimester, fmtDue, daysRemaining };
  }, [form.dueDate, lang]);

  const TRIMESTER_SUMMARY = {
    1: {
      fr: "Le premier trimestre est marqué par les grands changements hormonaux : fatigue, nausées possibles, seins sensibles — pendant que les organes essentiels de bébé se forment.",
      en: "The first trimester brings big hormonal shifts: fatigue, possible nausea, tender breasts — while baby's essential organs are forming.",
      es: "El primer trimestre trae grandes cambios hormonales: fatiga, posibles náuseas, senos sensibles — mientras se forman los órganos esenciales del bebé.",
    },
    2: {
      fr: "Le deuxième trimestre est souvent le plus confortable : l'énergie revient, le ventre s'arrondit, et vous sentirez bientôt (ou déjà) les premiers mouvements de bébé.",
      en: "The second trimester is often the most comfortable: energy returns, the belly rounds out, and you'll soon feel (or already are feeling) baby's first movements.",
      es: "El segundo trimestre suele ser el más cómodo: la energía regresa, el vientre se redondea, y pronto sentirás (o ya sientes) los primeros movimientos del bebé.",
    },
    3: {
      fr: "Le troisième trimestre est la dernière ligne droite : bébé prend du poids rapidement et se prépare à la naissance — bon moment pour préparer votre valise de maternité.",
      en: "The third trimester is the home stretch: baby is gaining weight quickly and getting ready for birth — a good time to pack your hospital bag.",
      es: "El tercer trimestre es la recta final: el bebé aumenta de peso rápidamente y se prepara para nacer — buen momento para preparar tu maleta de maternidad.",
    },
  };

  const infoCards = [
    { label: L.age, value: form.age || "—", icon: User, color: COLORS.sage, bg: "#F0F5EC" },
    { label: L.children, value: form.children, icon: Baby, color: COLORS.pink, bg: "#FDF0F3" },
  ];

  return (
    <div>
      {!standalone && (
        <h1 style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 24, color: COLORS.teal, marginBottom: 16 }}>{L.title}</h1>
      )}
      <div style={{
        background: `linear-gradient(135deg, ${COLORS.teal} 0%, #3f6178 100%)`,
        borderRadius: 24, padding: "34px 28px", textAlign: "center", color: "#fff",
        marginBottom: 20, position: "relative", overflow: "hidden",
      }}>
        <div style={{ position: "absolute", top: -30, right: -30, width: 140, height: 140, borderRadius: "50%", background: "rgba(255,255,255,0.06)" }} />
        <div style={{ position: "absolute", bottom: -40, left: -20, width: 110, height: 110, borderRadius: "50%", background: "rgba(255,255,255,0.05)" }} />

        <div style={{ position: "relative", display: "inline-block", margin: "0 auto 16px" }}>
          <div style={{
            width: 128, height: 128, borderRadius: "50%", background: COLORS.ochre, color: "#fff",
            display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "Fraunces, Georgia, serif",
            fontSize: 42, fontWeight: 700, flexShrink: 0, position: "relative", overflow: "hidden",
            border: "4px solid rgba(255,255,255,0.5)", boxShadow: "0 8px 20px rgba(0,0,0,0.18)",
          }}>
            {photo ? <img src={photo} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : initials}
          </div>
          <button
            onClick={() => photoInputRef.current?.click()}
            style={{
              position: "absolute", bottom: 0, right: 2, width: 36, height: 36, borderRadius: "50%",
              background: COLORS.ochre, border: "3px solid #fff", color: "#fff", cursor: "pointer",
              display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 2px 8px rgba(0,0,0,0.25)", fontSize: 15,
            }}
            aria-label={photo ? L.changePhoto : L.addPhoto}
          >
            📷
          </button>
          <input ref={photoInputRef} type="file" accept="image/*" onChange={handlePhotoChange} style={{ display: "none" }} />
        </div>
        {profilePhotoWarning && (
          <p style={{ fontSize: 11.5, color: "#fff", background: "rgba(179,38,30,0.35)", borderRadius: 10, padding: "6px 10px", margin: "0 0 10px", position: "relative" }}>{profilePhotoWarning}</p>
        )}
        {justSignedUp ? (
          <>
            <h2 style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 25, margin: "0 0 4px", position: "relative" }}>{L.welcomeTitle(form.name)}</h2>
            <p style={{ fontSize: 14, opacity: 0.9, margin: 0, position: "relative" }}>{L.welcomeSubtitle}</p>
          </>
        ) : (
          <>
            <h2 style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 25, margin: "0 0 4px", position: "relative" }}>{form.name}</h2>
            <p style={{ fontSize: 13, opacity: 0.85, margin: 0, position: "relative" }}>
              {L.memberSince} {new Date().toLocaleDateString(lang === "fr" ? "fr-CA" : lang === "es" ? "es-MX" : "en-CA", { month: "long", year: "numeric" })}
            </p>
          </>
        )}
      </div>

      {pregnancy && !editing && (
        <div style={{
          background: `linear-gradient(135deg, ${COLORS.pink} 0%, ${COLORS.ochre} 100%)`,
          borderRadius: 22, padding: "22px 24px", color: "#fff", marginBottom: 20,
          position: "relative", overflow: "hidden", boxShadow: "0 8px 20px rgba(217,139,164,0.30)",
        }}>
          <div style={{ position: "absolute", top: -24, right: -20, width: 100, height: 100, borderRadius: "50%", background: "rgba(255,255,255,0.10)" }} />
          <div style={{ display: "flex", alignItems: "flex-start", gap: 14, position: "relative" }}>
            <div style={{
              width: 44, height: 44, borderRadius: 13, background: "rgba(255,255,255,0.25)", flexShrink: 0,
              display: "flex", alignItems: "center", justifyContent: "center",
            }}>
              <Baby size={24} color="#fff" />
            </div>
            <div style={{ flex: 1, minWidth: 0 }}>
              <h3 style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 19, margin: "0 0 4px" }}>{L.congrats}</h3>
              <p style={{ fontSize: 13.5, margin: "0 0 10px", opacity: 0.95 }}>{L.dueOn(pregnancy.fmtDue)}</p>
              <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 12 }}>
                <span style={{
                  background: "rgba(255,255,255,0.25)", padding: "5px 12px", borderRadius: 999,
                  fontSize: 12.5, fontWeight: 700,
                }}>{L.weeksLabel(pregnancy.weeks, pregnancy.days)}</span>
                <span style={{
                  background: "rgba(255,255,255,0.25)", padding: "5px 12px", borderRadius: 999,
                  fontSize: 12.5, fontWeight: 700,
                }}>{L.trimesterLabel(pregnancy.trimester)}</span>
                <span style={{
                  background: "rgba(255,255,255,0.25)", padding: "5px 12px", borderRadius: 999,
                  fontSize: 12.5, fontWeight: 700,
                }}>{L.daysRemainingLabel(pregnancy.daysRemaining)}</span>
              </div>
              <p style={{ fontSize: 13, lineHeight: 1.6, margin: 0, background: "rgba(255,255,255,0.18)", borderRadius: 12, padding: "10px 12px" }}>
                {TRIMESTER_SUMMARY[pregnancy.trimester][lang]}
              </p>
            </div>
          </div>
        </div>
      )}

      <Card style={{ marginBottom: 8 }}>
        {editing ? (
          <div>
            {!justSignedUp && (
              <>
                <label style={labelStyle}>{L.name}
                  <input style={inputStyle} value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} />
                </label>
                <label style={labelStyle}>{L.email}
                  <input style={inputStyle} value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} />
                </label>
                {hasSession && (
                  <div style={{ marginBottom: 18 }}>
                    <label style={labelStyle}>{L.currentPasswordLabel}
                      <div style={{ position: "relative" }}>
                        <input type="text" readOnly value="••••••••" style={{ ...inputStyle, color: COLORS.muted, background: "#F5F1E8" }} />
                      </div>
                    </label>
                    {!showPasswordFields ? (
                      <button
                        type="button" onClick={() => setShowPasswordFields(true)}
                        style={{ background: "none", border: "none", padding: 0, color: COLORS.teal, fontSize: 12.5, fontWeight: 700, cursor: "pointer" }}
                      >{L.changePassword}</button>
                    ) : (
                      <div style={{ display: "flex", flexDirection: "column", gap: 10, marginTop: 8, background: COLORS.cream, borderRadius: 12, padding: 14 }}>
                        <label style={{ position: "relative", display: "block" }}>
                          <input
                            type={showNewPassword ? "text" : "password"} placeholder={L.newPassword} value={newPassword}
                            onChange={(e) => setNewPassword(e.target.value)}
                            style={{ ...inputStyle, paddingRight: 40 }}
                          />
                          <button type="button" onClick={() => setShowNewPassword((v) => !v)} style={{ position: "absolute", right: 10, top: "50%", transform: "translateY(-50%)", background: "none", border: "none", cursor: "pointer", padding: 4, color: COLORS.muted }}>
                            {showNewPassword ? <EyeOff size={16} /> : <Eye size={16} />}
                          </button>
                        </label>
                        <label style={{ position: "relative", display: "block" }}>
                          <input
                            type={showConfirmPassword ? "text" : "password"} placeholder={L.confirmPassword} value={confirmPassword}
                            onChange={(e) => setConfirmPassword(e.target.value)}
                            style={{ ...inputStyle, paddingRight: 40 }}
                          />
                          <button type="button" onClick={() => setShowConfirmPassword((v) => !v)} style={{ position: "absolute", right: 10, top: "50%", transform: "translateY(-50%)", background: "none", border: "none", cursor: "pointer", padding: 4, color: COLORS.muted }}>
                            {showConfirmPassword ? <EyeOff size={16} /> : <Eye size={16} />}
                          </button>
                        </label>
                        {passwordMsg && (
                          <p style={{ fontSize: 12, margin: 0, color: passwordMsg === L.passwordChanged ? COLORS.sage : "#B3261E", fontWeight: 600 }}>{passwordMsg}</p>
                        )}
                        <div style={{ display: "flex", gap: 8 }}>
                          <button
                            type="button" onClick={handleChangePassword} disabled={changingPassword || !newPassword || !confirmPassword}
                            style={{
                              background: COLORS.teal, color: "#fff", border: "none", padding: "9px 18px",
                              borderRadius: 999, fontWeight: 700, fontSize: 13, cursor: (changingPassword || !newPassword || !confirmPassword) ? "default" : "pointer",
                              opacity: (changingPassword || !newPassword || !confirmPassword) ? 0.5 : 1,
                            }}
                          >{changingPassword ? L.saving : L.updatePassword}</button>
                          <button
                            type="button" onClick={() => { setShowPasswordFields(false); setNewPassword(""); setConfirmPassword(""); setPasswordMsg(""); }}
                            style={{ background: "transparent", color: COLORS.muted, border: `1px solid ${COLORS.line}`, padding: "9px 18px", borderRadius: 999, fontWeight: 600, fontSize: 13, cursor: "pointer" }}
                          >{L.cancel}</button>
                        </div>
                      </div>
                    )}
                  </div>
                )}
              </>
            )}
            <div style={{ display: "flex", gap: 14, flexWrap: "wrap" }}>
              <label style={{ ...labelStyle, flex: 1, minWidth: 160 }}>{L.country}
                <select style={inputStyle} value={form.country} onChange={(e) => setForm({ ...form, country: e.target.value })}>
                  {COUNTRIES.map((c) => <option key={c.code} value={c.code}>{c.label[lang]}</option>)}
                </select>
              </label>
              <label style={{ ...labelStyle, flex: 1, minWidth: 160 }}>{L.language}
                <select style={inputStyle} value={form.language} onChange={(e) => setForm({ ...form, language: e.target.value })}>
                  {LANGUAGES.map((l) => <option key={l.code} value={l.code}>{l.label[lang]}</option>)}
                </select>
              </label>
            </div>
            <div style={{ display: "flex", gap: 14, flexWrap: "wrap" }}>
              <label style={{ ...labelStyle, flex: 1, minWidth: 140 }}>{L.birthdate}
                <FlexibleDateInput style={inputStyle} value={form.birthdate} onChange={(bd) => {
                  const computed = computeAgeFromBirthdate(bd);
                  const years = computed ? (computed.unit === "months" ? Math.round(computed.value / 12) : computed.value) : "";
                  setForm({ ...form, birthdate: bd, age: years });
                }} />
                {form.age !== "" && <span style={{ fontSize: 12, color: COLORS.muted, marginTop: 2 }}>{L.ageComputed(form.age)}</span>}
              </label>
              <label style={{ ...labelStyle, flex: 1, minWidth: 200 }}>{L.due}
                <input type="date" style={inputStyle} value={form.dueDate} onChange={(e) => handleDueDateChange(e.target.value)} />
              </label>
            </div>
            {form.dueDate && !children.some((c) => c.birthdate && new Date(c.birthdate) > new Date()) && (
              <div style={{ background: "#FDF0F3", border: `1.5px dashed ${COLORS.pink}80`, borderRadius: 14, padding: 14, display: "flex", gap: 12, alignItems: "flex-start", marginBottom: 16 }}>
                <div style={{ position: "relative", flexShrink: 0 }}>
                  <label style={{
                    display: "flex", alignItems: "center", justifyContent: "center", width: 52, height: 52, borderRadius: "50%",
                    background: "#fff", border: `2px dashed ${COLORS.pink}80`, cursor: "pointer", overflow: "hidden", fontSize: 20,
                  }}>
                    {upcomingChild.photo ? <img src={upcomingChild.photo} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : "📷"}
                    <input type="file" accept="image/*" onChange={handleUpcomingChildPhoto} style={{ display: "none" }} />
                  </label>
                </div>
                <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: 8, minWidth: 0 }}>
                  <span style={{ display: "inline-block", background: COLORS.pink, color: "#fff", fontSize: 10.5, fontWeight: 700, padding: "2px 9px", borderRadius: 999, alignSelf: "flex-start" }}>{L.upcomingBadge}</span>
                  {upcomingPhotoWarning && <p style={{ fontSize: 11, color: "#B3261E", margin: 0 }}>{upcomingPhotoWarning}</p>}
                  <input
                    placeholder={L.upcomingNamePlaceholder} value={upcomingChild.name}
                    onChange={(e) => updateUpcomingChild("name", e.target.value)}
                    style={{ padding: "9px 12px", borderRadius: 10, border: `1px solid ${COLORS.line}`, fontSize: 13.5, boxSizing: "border-box" }}
                  />
                  <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                    <span style={{ fontSize: 11.5, color: COLORS.muted, fontWeight: 600 }}>{L.childBirthdate}</span>
                    <FlexibleDateInput
                      value={upcomingChild.birthdate || form.dueDate}
                      onChange={(v) => updateUpcomingChild("birthdate", v)}
                      style={{ padding: "9px 10px", borderRadius: 10, border: `1px solid ${COLORS.line}`, fontSize: 13.5, boxSizing: "border-box" }}
                    />
                    <span style={{ fontSize: 11, color: COLORS.muted, fontStyle: "italic" }}>{L.upcomingDueNote}</span>
                  </div>
                  {upcomingAddError && <p style={{ fontSize: 11.5, color: "#B3261E", margin: 0 }}>{upcomingAddError}</p>}
                  <button type="button" onClick={addUpcomingChildNow} disabled={addingUpcoming} style={{
                    alignSelf: "flex-start", background: COLORS.pink, color: "#fff", border: "none", padding: "8px 16px",
                    borderRadius: 999, fontWeight: 700, fontSize: 12.5, cursor: addingUpcoming ? "default" : "pointer", opacity: addingUpcoming ? 0.7 : 1,
                  }}>{addingUpcoming ? L.saving : L.addChildBtn}</button>
                </div>
              </div>
            )}

            {form.dueDate && (
              <div style={{ marginBottom: 16 }}>
                <span style={{ ...labelStyle, display: "block", marginBottom: 6 }}>{L.pregnancyProfileLabel}</span>
                {[
                  ["standard", L.pregnancyProfileStandard],
                  ["35to40", L.pregnancyProfile3540],
                  ["40plus", L.pregnancyProfile40plus],
                  ["risque", L.pregnancyProfileRisk],
                ].map(([key, label]) => (
                  <label key={key} style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13.5, color: COLORS.text, marginBottom: 6, cursor: "pointer" }}>
                    <input
                      type="checkbox"
                      checked={form.pregnancyProfile.includes(key)}
                      onChange={(e) => {
                        // Sélection unique : cocher une option désélectionne automatiquement les autres.
                        setForm((f) => ({ ...f, pregnancyProfile: e.target.checked ? [key] : [] }));
                      }}
                    />
                    {label}
                  </label>
                ))}
              </div>
            )}
            <BatteryNotice lang={lang} />
            <label style={{ ...labelStyle, maxWidth: 320 }}>{L.children}
              {children.filter((c) => !c.birthdate || new Date(c.birthdate) <= new Date()).length > 0 && (
                <span style={{ fontWeight: 400, color: COLORS.sage }}>
                  {" "}— {L.currentChildrenCount(children.filter((c) => !c.birthdate || new Date(c.birthdate) <= new Date()).length)}
                </span>
              )}
              <input
                type="number" min={0} placeholder="0" style={inputStyle}
                value={expectedChildrenCount}
                onChange={(e) => setExpectedChildrenCount(e.target.value)}
              />
            </label>
            {children.length > 0 && (
              <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginBottom: 14 }}>
                {children.map((c) => (
                  <span key={c.id} style={{
                    display: "inline-flex", alignItems: "center", gap: 6, background: COLORS.cream,
                    borderRadius: 999, padding: "5px 12px 5px 5px", fontSize: 12.5, fontWeight: 600, color: COLORS.text,
                  }}>
                    <span style={{
                      width: 22, height: 22, borderRadius: "50%", overflow: "hidden", flexShrink: 0,
                      background: COLORS.pink, color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 10, fontWeight: 700,
                    }}>
                      {c.photo ? <img src={c.photo} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : (c.name?.[0] || "?")}
                    </span>
                    {c.name}
                  </span>
                ))}
              </div>
            )}

            {(() => {
              const target = Number(expectedChildrenCount);
              const bornChildren = children.filter((c) => !c.birthdate || new Date(c.birthdate) <= new Date());
              return expectedChildrenCount !== "" && target >= 0 && target < bornChildren.length;
            })() && (
              <div style={{ background: "#FDEDEA", borderRadius: 14, padding: 14, marginBottom: 16 }}>
                <p style={{ fontSize: 13, fontWeight: 600, color: COLORS.text, margin: "0 0 10px" }}>
                  {L.selectChildToRemove(Number(expectedChildrenCount) === 0 ? 0 : children.filter((c) => !c.birthdate || new Date(c.birthdate) <= new Date()).length - Number(expectedChildrenCount))}
                </p>
                <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 10 }}>
                  {children.filter((c) => !c.birthdate || new Date(c.birthdate) <= new Date()).map((c) => (
                    <label key={c.id} style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13.5, color: COLORS.text, cursor: "pointer" }}>
                      <input
                        type="checkbox" checked={childrenToRemove.includes(c.id)}
                        onChange={(e) => setChildrenToRemove((prev) => e.target.checked ? [...prev, c.id] : prev.filter((id) => id !== c.id))}
                      />
                      {c.name}
                    </label>
                  ))}
                </div>
                {removeChildrenError && <p style={{ fontSize: 11.5, color: "#B3261E", margin: "0 0 8px" }}>{removeChildrenError}</p>}
                <button
                  type="button" onClick={confirmRemoveChildren}
                  disabled={removingChildren || childrenToRemove.length === 0}
                  style={{
                    background: "#B3261E", color: "#fff", border: "none", padding: "8px 16px", borderRadius: 999,
                    fontWeight: 700, fontSize: 12.5, cursor: (removingChildren || childrenToRemove.length === 0) ? "default" : "pointer",
                    opacity: (removingChildren || childrenToRemove.length === 0) ? 0.5 : 1,
                  }}
                >{removingChildren ? L.saving : L.confirmRemove}</button>
              </div>
            )}

            {(() => {
              const target = Number(expectedChildrenCount);
              // On ne compte que les enfants déjà nés (date de naissance passée ou vide) — l'enfant "à
              // venir" (date future, ajouté séparément plus haut) ne doit pas réduire ce total.
              const bornCount = children.filter((c) => !c.birthdate || new Date(c.birthdate) <= new Date()).length;
              // La carte d'ajout reste visible tant que le nombre d'enfants déjà ajoutés n'a pas
              // atteint le nombre indiqué par la personne (éviter d'en proposer plus que demandé).
              return target > 0 && bornCount < target;
            })() && (
            <div style={{ background: COLORS.cream, borderRadius: 14, padding: 14, display: "flex", gap: 12, alignItems: "flex-start", marginBottom: 16 }}>
              <div style={{ position: "relative", flexShrink: 0 }}>
                <label style={{
                  display: "flex", alignItems: "center", justifyContent: "center", width: 52, height: 52, borderRadius: "50%",
                  background: "#fff", border: `2px dashed ${COLORS.pink}80`, cursor: "pointer", overflow: "hidden", fontSize: 20,
                }}>
                  {childDraft.photo ? <img src={childDraft.photo} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : "📷"}
                  <input type="file" accept="image/*" onChange={handleChildDraftPhoto} style={{ display: "none" }} />
                </label>
              </div>
              <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: 8, minWidth: 0 }}>
                {childPhotoWarning && <p style={{ fontSize: 11, color: "#B3261E", margin: 0 }}>{childPhotoWarning}</p>}
                <input
                  placeholder={L.childName(children.length)} value={childDraft.name}
                  onChange={(e) => updateChildDraftField("name", e.target.value)}
                  style={{ padding: "9px 12px", borderRadius: 10, border: `1px solid ${COLORS.line}`, fontSize: 13.5, boxSizing: "border-box" }}
                />
                <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                  <span style={{ fontSize: 11.5, color: COLORS.muted, fontWeight: 600 }}>{L.childBirthdate}</span>
                  <FlexibleDateInput
                    value={childDraft.birthdate}
                    onChange={(v) => updateChildDraftField("birthdate", v)}
                    style={{ padding: "9px 10px", borderRadius: 10, border: `1px solid ${COLORS.line}`, fontSize: 13.5, boxSizing: "border-box" }}
                  />
                  {childDraft.birthdate && (() => {
                    const a = computeAgeFromBirthdate(childDraft.birthdate);
                    return a ? <span style={{ fontSize: 11.5, color: COLORS.muted }}>{L.childAgeComputed(a.value, a.unit)}</span> : null;
                  })()}
                </div>
                {childAddError && <p style={{ fontSize: 11.5, color: "#B3261E", margin: 0 }}>{childAddError}</p>}
                <button type="button" onClick={addChildNow} disabled={addingChild || !childDraft.name.trim()} style={{
                  alignSelf: "flex-start", background: COLORS.teal, color: "#fff", border: "none", padding: "8px 16px",
                  borderRadius: 999, fontWeight: 700, fontSize: 12.5, cursor: (addingChild || !childDraft.name.trim()) ? "default" : "pointer",
                  opacity: (addingChild || !childDraft.name.trim()) ? 0.5 : 1,
                }}>{addingChild ? L.saving : L.addChildBtn}</button>
              </div>
            </div>
            )}

            {(() => {
              const bornCount = children.filter((c) => !c.birthdate || new Date(c.birthdate) <= new Date()).length;
              const target = Number(expectedChildrenCount);
              const childrenComplete = expectedChildrenCount === "" || target === bornCount;
              const formComplete = form.name.trim().length > 0 && childrenComplete;
              if (formComplete) {
                return (
                  <div style={{ display: "flex", gap: 10, marginTop: 6 }}>
                    <button onClick={handleSave} disabled={saving} style={{ background: COLORS.teal, color: "#fff", border: "none", padding: "10px 22px", borderRadius: 999, fontWeight: 700, fontSize: 14, cursor: saving ? "default" : "pointer", opacity: saving ? 0.7 : 1 }}>{saving ? L.saving : justSignedUp ? L.continueBtn : L.save}</button>
                    {!justSignedUp && <button onClick={() => setEditing(false)} style={{ background: "transparent", color: COLORS.muted, border: `1px solid ${COLORS.line}`, padding: "10px 22px", borderRadius: 999, fontWeight: 600, fontSize: 14, cursor: "pointer" }}>{L.cancel}</button>}
                  </div>
                );
              }
              // Le bouton reste caché tant que le formulaire n'est pas complet (ex. il manque des enfants
              // par rapport au nombre indiqué) — on explique pourquoi plutôt que de laisser un vide.
              return (
                <p style={{ fontSize: 12.5, color: COLORS.muted, fontStyle: "italic", marginTop: 6 }}>
                  {!formComplete && !form.name.trim().length
                    ? L.incompleteFormName
                    : L.incompleteFormChildren(Math.max(0, target - bornCount))}
                </p>
              );
            })()}
          </div>
        ) : (
          <div>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))", gap: 12, marginBottom: 20 }}>
              {infoCards.map((c, i) => (
                <div key={i} style={{ background: c.bg, borderRadius: 14, padding: "14px 16px", borderTop: `3px solid ${c.color}` }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6 }}>
                    <div style={{ width: 26, height: 26, borderRadius: 8, background: c.color, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                      <c.icon size={14} color="#fff" />
                    </div>
                    <div style={{ fontSize: 11.5, color: c.color, fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.02em" }}>{c.label}</div>
                  </div>
                  <div style={{ fontSize: 15, color: COLORS.text, fontWeight: 700 }}>{c.value}</div>
                </div>
              ))}
            </div>
            <button onClick={() => {
              const bornCount = children.filter((c) => !c.birthdate || new Date(c.birthdate) <= new Date()).length;
              setExpectedChildrenCount(bornCount > 0 ? String(bornCount) : "");
              setEditing(true);
            }} style={{
              display: "inline-flex", alignItems: "center", gap: 7, background: COLORS.teal, color: "#fff", border: "none",
              padding: "10px 22px", borderRadius: 999, fontWeight: 700, fontSize: 14, cursor: "pointer",
              boxShadow: "0 4px 10px rgba(47,72,88,0.25)",
            }}><User size={14} /> {L.edit}</button>
            {saved && <span style={{ marginLeft: 12, fontSize: 13, color: COLORS.sage, fontWeight: 700 }}>✓ {L.saved}</span>}
          </div>
        )}
      </Card>
      {errorMsg && <p style={{ fontSize: 12.5, color: "#B3261E", marginTop: 10, marginBottom: 0, textAlign: "center", fontWeight: 600 }}>{errorMsg}</p>}
      {!standalone && !hasSession && <p style={{ fontSize: 11.5, color: COLORS.muted, marginTop: 4, marginBottom: 24, textAlign: "center", fontStyle: "italic" }}>{L.demo}</p>}

      {!standalone && (
        <>
          <ChildrenManager lang={lang} children={children} setChildren={setChildren} session={session} />
          <CoParentInvite lang={lang} />
        </>
      )}
    </div>
  );
}

/* ---------------- CHILDREN MANAGER (multi-child, light) ---------------- */
function ChildrenManager({ lang, children, setChildren, session }) {
  const [editingId, setEditingId] = useState(null);
  const [editForm, setEditForm] = useState({ name: "", birthdate: "", photo: null, photoFile: null });
  const [editSaving, setEditSaving] = useState(false);
  const [editErrorMsg, setEditErrorMsg] = useState("");
  const [editPhotoWarning, setEditPhotoWarning] = useState("");
  const L = lang === "fr"
    ? { title: "Mes enfants", subtitle: "Modifiez les informations de chacun de vos enfants (nom, date de naissance, photo).",
        name: "Prénom", birthdate: "Date de naissance", empty: "Aucun enfant enregistré pour l'instant — ajoutez-en un dans « Modifier mon profil ».",
        edit: "Modifier", save: "Enregistrer", cancel: "Annuler", photo: "Photo (optionnel)",
        errorEdit: "Impossible de modifier l'enfant pour le moment. Réessayez.",
        photoTooLarge: "📵 Cette photo est trop volumineuse pour votre appareil en ce moment. Vous pouvez continuer sans photo, ou réessayer avec une photo plus légère." }
    : lang === "es"
    ? { title: "Mis hijos", subtitle: "Modifica la información de cada uno de tus hijos (nombre, fecha de nacimiento, foto).",
        name: "Nombre", birthdate: "Fecha de nacimiento", empty: "Aún no hay hijos registrados — agrega uno en « Editar mi perfil ».",
        edit: "Editar", save: "Guardar", cancel: "Cancelar", photo: "Foto (opcional)",
        errorEdit: "No se pudo editar al hijo/a por ahora. Inténtalo de nuevo.",
        photoTooLarge: "📵 Esta foto es demasiado pesada para tu dispositivo en este momento. Puedes continuar sin foto, o intentar con una foto más liviana." }
    : { title: "My children", subtitle: "Edit each of your children's information (name, date of birth, photo).",
        name: "First name", birthdate: "Date of birth", empty: "No children registered yet — add one in \"Edit my profile\".",
        edit: "Edit", save: "Save", cancel: "Cancel", photo: "Photo (optional)",
        errorEdit: "Couldn't edit your child right now. Please try again.",
        photoTooLarge: "📵 This photo is too large for your device right now. You can continue without a photo, or try again with a lighter photo." };

  const hasSession = !!(session?.access_token && session?.user?.id);

  const startEdit = (ch) => {
    setEditingId(ch.id);
    setEditForm({ name: ch.name || "", birthdate: ch.birthdate || "", photo: ch.photo || null, photoFile: null });
    setEditErrorMsg("");
    setEditPhotoWarning("");
  };

  const handleEditPhoto = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const { dataUrl, file: resizedFile, tooLarge } = await resizeImageForUpload(file);
    if (tooLarge) { setEditPhotoWarning(L.photoTooLarge); e.target.value = ""; return; }
    setEditPhotoWarning("");
    setEditForm((f) => ({ ...f, ...(dataUrl ? { photo: dataUrl } : {}), photoFile: resizedFile }));
  };

  const saveEdit = async () => {
    if (!editForm.name.trim()) return;
    setEditErrorMsg("");
    setEditSaving(true);
    try {
      let photoUrl = editForm.photo && !editForm.photo.startsWith("blob:") ? editForm.photo : null;
      if (editForm.photoFile && hasSession) {
        photoUrl = await supabaseUploadPhoto(editForm.photoFile, session.user.id, session.access_token);
        if (editForm.photo && editForm.photo.startsWith("blob:")) URL.revokeObjectURL(editForm.photo);
      }
      if (hasSession && typeof editingId === "string" && !editingId.startsWith("local-")) {
        const row = await supabaseUpdateChild(editingId, { name: editForm.name.trim(), birthdate: editForm.birthdate || null, photo_data: photoUrl }, session.access_token);
        setChildren((c) => c.map((ch) => (ch.id === editingId ? mapChildRow(row) : ch)));
      } else {
        setChildren((c) => c.map((ch) => (ch.id === editingId ? { ...ch, name: editForm.name.trim(), birthdate: editForm.birthdate, photo: photoUrl } : ch)));
      }
      setEditingId(null);
    } catch (err) {
      setEditErrorMsg(L.errorEdit);
    }
    setEditSaving(false);
  };

  const inputStyle = { flex: 1, minWidth: 120, padding: "9px 12px", borderRadius: 10, border: `1px solid ${COLORS.line}`, fontSize: 13.5 };

  return (
    <Card style={{ marginBottom: 20, borderTop: `4px solid ${COLORS.pink}` }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 4 }}>
        <div style={{ width: 32, height: 32, borderRadius: 10, background: COLORS.pink, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
          <Baby size={16} color="#fff" />
        </div>
        <h3 style={{ margin: 0, fontFamily: "Fraunces, Georgia, serif", fontSize: 18, color: COLORS.teal }}>{L.title}</h3>
      </div>
      <p style={{ margin: "0 0 14px", fontSize: 13, color: COLORS.muted }}>{L.subtitle}</p>

      {children.length > 0 ? (
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {children.map((ch) => editingId === ch.id ? (
            <div key={ch.id} style={{ background: "#FDF0F3", borderRadius: 12, padding: "12px 14px" }}>
              <div style={{ display: "flex", gap: 8, alignItems: "center", marginBottom: 8 }}>
                <label style={{
                  width: 40, height: 40, borderRadius: "50%", background: "#fff", border: `1px dashed ${COLORS.line}`,
                  display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, overflow: "hidden", cursor: "pointer",
                }}>
                  {editForm.photo ? <img src={editForm.photo} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : "📷"}
                  <input type="file" accept="image/*" onChange={handleEditPhoto} style={{ display: "none" }} />
                </label>
                <span style={{ fontSize: 12, color: COLORS.muted }}>{L.photo}</span>
              </div>
              {editPhotoWarning && <p style={{ fontSize: 11.5, color: "#B3261E", margin: "0 0 8px" }}>{editPhotoWarning}</p>}
              <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 8 }}>
                <input style={inputStyle} placeholder={L.name} value={editForm.name} onChange={(e) => setEditForm({ ...editForm, name: e.target.value })} />
                <FlexibleDateInput style={inputStyle} value={editForm.birthdate} onChange={(v) => setEditForm({ ...editForm, birthdate: v })} />
              </div>
              {editErrorMsg && <p style={{ fontSize: 12, color: "#B3261E", margin: "0 0 8px" }}>{editErrorMsg}</p>}
              <div style={{ display: "flex", gap: 8 }}>
                <button onClick={saveEdit} disabled={editSaving} style={{ padding: "8px 16px", borderRadius: 10, border: "none", background: COLORS.teal, color: "#fff", fontWeight: 700, fontSize: 12.5, cursor: editSaving ? "default" : "pointer", opacity: editSaving ? 0.7 : 1 }}>{editSaving ? "…" : L.save}</button>
                <button onClick={() => setEditingId(null)} style={{ padding: "8px 16px", borderRadius: 10, border: `1px solid ${COLORS.line}`, background: "transparent", color: COLORS.muted, fontWeight: 600, fontSize: 12.5, cursor: "pointer" }}>{L.cancel}</button>
              </div>
            </div>
          ) : (
            <div key={ch.id} style={{
              display: "flex", alignItems: "center", justifyContent: "space-between", background: "#FDF0F3",
              borderRadius: 12, padding: "10px 14px", gap: 8, flexWrap: "wrap",
            }}>
              <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                <div style={{
                  width: 34, height: 34, borderRadius: "50%", background: COLORS.pink, color: "#fff", flexShrink: 0,
                  display: "flex", alignItems: "center", justifyContent: "center", fontSize: 13, fontWeight: 700, overflow: "hidden",
                }}>
                  {ch.photo ? <img src={ch.photo} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : (ch.name?.[0] || "?").toUpperCase()}
                </div>
                <div>
                  <span style={{ fontWeight: 700, color: COLORS.text, fontSize: 14 }}>{ch.name}</span>
                  {ch.birthdate && <span style={{ color: COLORS.muted, fontSize: 12.5, marginLeft: 8 }}>{ch.birthdate}</span>}
                </div>
              </div>
              <button onClick={() => startEdit(ch)} style={{ background: "none", border: "none", color: COLORS.teal, fontSize: 12, fontWeight: 700, cursor: "pointer" }}>{L.edit}</button>
            </div>
          ))}
        </div>
      ) : (
        <p style={{ fontSize: 13, color: COLORS.muted, fontStyle: "italic", margin: 0 }}>{L.empty}</p>
      )}
    </Card>
  );
}

/* ---------------- CO-PARENT INVITE (UI only — needs backend to actually send/share) ---------------- */
