// Faint wallpaper pattern of baby items behind the comments (deterministic, computed once)
const FORUM_PATTERN_EMOJIS = ["🍼", "🧸", "🧷", "🎀", "🪀"];
const FORUM_PATTERN = Array.from({ length: 30 }).map((_, idx) => {
  const row = Math.floor(idx / 6);
  const col = idx % 6;
  return {
    emoji: FORUM_PATTERN_EMOJIS[idx % FORUM_PATTERN_EMOJIS.length],
    top: `${row * 18 + (col % 2 === 0 ? 2 : 9)}%`,
    left: `${col * 17 + (row % 2 === 0 ? 2 : 6)}%`,
    rotate: ((idx * 37) % 40) - 20,
    size: 20 + (idx % 3) * 4,
  };
});

function ForumSection({ lang, isMember, goTo }) {
  const [posts, setPosts] = useState(FORUM_SEED);
  const [name, setName] = useState("");
  const [message, setMessage] = useState("");
  const [reactions, setReactions] = useState({}); // { [postIndex]: "like" | "dislike" }
  const [translations, setTranslations] = useState({}); // { [postIndex]: translatedText }
  const [showOriginal, setShowOriginal] = useState({}); // { [postIndex]: bool } — true = affiche le texte original plutôt que la traduction
  const [translatingIds, setTranslatingIds] = useState({}); // { [postIndex]: bool }
  const [translateErrors, setTranslateErrors] = useState({}); // { [postIndex]: bool }
  const [translatingAll, setTranslatingAll] = useState(false);
  const [openReplies, setOpenReplies] = useState({}); // { [postIndex]: bool } — panneau de réponses déplié
  const [replyDrafts, setReplyDrafts] = useState({}); // { [postIndex]: string } — texte en cours de rédaction
  const [extraReplies, setExtraReplies] = useState({}); // { [postIndex]: [{ author, text }] } — réponses ajoutées dans cette session

  const setReaction = (i, type) => {
    setReactions((prev) => {
      const was = prev[i];
      const next = was === type ? null : type;
      setPosts((prevPosts) => prevPosts.map((p, idx) => {
        if (idx !== i) return p;
        let likes = p.likes || 0;
        let dislikes = p.dislikes || 0;
        if (was === "like") likes -= 1;
        if (was === "dislike") dislikes -= 1;
        if (next === "like") likes += 1;
        if (next === "dislike") dislikes += 1;
        return { ...p, likes, dislikes };
      }));
      return { ...prev, [i]: next };
    });
  };

  const L = lang === "fr"
    ? {
        title: "Communauté", subtitle: "Un espace pour échanger avec d'autres parents, poser vos questions et partager vos petites victoires.",
        nameLabel: "Votre prénom", messageLabel: "Votre message",
        namePlaceholder: "Ex. Alex", messagePlaceholder: "Partagez une question ou une expérience…",
        post: "Publier", replies: (n) => `${n} réponse${n > 1 ? "s" : ""}`, empty: "Écrivez le premier commentaire ci-dessous.",
        demo: "Démonstration : les publications restent seulement dans cette session, elles ne sont pas partagées avec d'autres utilisatrices.",
        translate: "Traduire", translating: "Traduction…", seeTranslation: "Voir la traduction", seeOriginal: "Voir l'original",
        translatedNote: "Traduit automatiquement", translateError: "La traduction a échoué. Réessayer.",
        translateAll: "Traduire tous les commentaires", translateAllBusy: "Traduction en cours…",
        replyPlaceholder: "Écrire une réponse…", replySend: "Répondre", translateHint: "🌐 Écrivez dans votre langue — les autres pourront traduire votre commentaire automatiquement dans la leur.",
      }
    : lang === "es"
    ? {
        title: "Comunidad", subtitle: "Un espacio para conectar con otros padres, hacer tus preguntas y compartir tus pequeñas victorias.",
        nameLabel: "Tu nombre", messageLabel: "Tu mensaje",
        namePlaceholder: "Ej. Alex", messagePlaceholder: "Comparte una pregunta o una experiencia…",
        post: "Publicar", replies: (n) => `${n} respuesta${n > 1 ? "s" : ""}`, empty: "Escribe el primer comentario abajo.",
        demo: "Demostración: las publicaciones se mantienen solo en esta sesión, no se comparten con otras usuarias.",
        translate: "Traducir", translating: "Traduciendo…", seeTranslation: "Ver traducción", seeOriginal: "Ver original",
        translatedNote: "Traducido automáticamente", translateError: "La traducción falló. Reintentar.",
        translateAll: "Traducir todos los comentarios", translateAllBusy: "Traduciendo…",
        replyPlaceholder: "Escribir una respuesta…", replySend: "Responder", translateHint: "🌐 Escribe en tu idioma — otras personas podrán traducir tu comentario automáticamente al suyo.",
      }
    : {
        title: "Community", subtitle: "A space to connect with other parents, ask questions, and share your small wins.",
        nameLabel: "Your first name", messageLabel: "Your message",
        namePlaceholder: "E.g. Alex", messagePlaceholder: "Share a question or an experience…",
        post: "Post", replies: (n) => `${n} repl${n > 1 ? "ies" : "y"}`, empty: "Write the first comment below.",
        demo: "Demo only: posts stay within this session and aren't shared with other users.",
        translate: "Translate", translating: "Translating…", seeTranslation: "See translation", seeOriginal: "See original",
        translatedNote: "Auto-translated", translateError: "Translation failed. Retry.",
        translateAll: "Translate all comments", translateAllBusy: "Translating…",
        replyPlaceholder: "Write a reply…", replySend: "Reply", translateHint: "🌐 Write in your own language — others will be able to automatically translate your comment into theirs.",
      };

  const inputStyle = { width: "100%", padding: "7px 10px", borderRadius: 9, border: `1px solid ${COLORS.line}`, fontSize: 12.5, boxSizing: "border-box", fontFamily: "inherit" };
  const labelStyle = { display: "flex", flexDirection: "column", gap: 4, fontSize: 12, color: COLORS.muted, fontWeight: 600, marginBottom: 10 };

  const submitPost = () => {
    if (!message.trim()) return;
    // Chaque personne écrit dans sa propre langue (celle de l'app au moment de la publication) — la
    // traduction vers les autres langues se fait à la demande, à la lecture, plutôt qu'à l'écriture.
    const newPost = {
      author: name.trim() || (lang === "fr" ? "Anonyme" : lang === "es" ? "Anónimo" : "Anonymous"),
      text: message.trim(), origLang: lang,
      replies: 0, likes: 0,
    };
    setPosts([newPost, ...posts]);
    setMessage("");
  };

  // Traduit le texte d'un commentaire vers la langue active de l'app en utilisant Claude.
  const langName = (code) => (code === "fr" ? "French" : code === "es" ? "Spanish" : "English");
  const translateOne = async (i) => {
    const p = posts[i];
    if (!p || p.fr !== undefined) return; // rien à faire pour les publications déjà pré-traduites (contenu de départ)
    setTranslatingIds((prev) => ({ ...prev, [i]: true }));
    setTranslateErrors((prev) => ({ ...prev, [i]: false }));
    try {
      const response = await fetch("/api/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-6",
          max_tokens: 400,
          messages: [{
            role: "user",
            content: `Translate the following ${langName(p.origLang)} text into ${langName(lang)}. Keep the tone, emojis and punctuation as close to the original as possible. Respond with ONLY the translated text, nothing else — no quotes, no preamble.\n\nText: ${p.text}`,
          }],
        }),
      });
      const data = await response.json();
      const translated = (data.content || []).map((b) => b.text || "").join("").trim();
      if (!translated) throw new Error("empty translation");
      setTranslations((prev) => ({ ...prev, [i]: translated }));
      setShowOriginal((prev) => ({ ...prev, [i]: false }));
    } catch (e) {
      setTranslateErrors((prev) => ({ ...prev, [i]: true }));
    } finally {
      setTranslatingIds((prev) => ({ ...prev, [i]: false }));
    }
  };

  const translateAll = async () => {
    const pending = posts
      .map((p, i) => ({ p, i }))
      .filter(({ p, i }) => p.fr === undefined && p.origLang !== lang && translations[i] === undefined);
    if (pending.length === 0) return;
    setTranslatingAll(true);
    await Promise.all(pending.map(({ i }) => translateOne(i)));
    setTranslatingAll(false);
  };

  const hasTranslatable = posts.some((p, i) => p.fr === undefined && p.origLang !== lang && translations[i] === undefined);

  return (
    <div>
      <div style={{
        display: "flex", alignItems: "center", justifyContent: "space-between", gap: 18,
        background: `linear-gradient(135deg, ${COLORS.sage} 0%, #7a9479 100%)`,
        border: "none", borderRadius: 20, padding: "20px 24px", marginBottom: 18,
        boxShadow: "0 2px 14px rgba(47,72,88,0.06)",
      }}>
        <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
          <div style={{ width: 62, height: 62, borderRadius: 18, background: "rgba(255,255,255,0.25)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
            <Users size={28} color="#fff" />
          </div>
          <div>
            <h2 style={{ margin: 0, fontFamily: "Fraunces, Georgia, serif", fontSize: 22, color: "#fff" }}>{L.title}</h2>
            <p style={{ margin: "4px 0 0", color: "#fff", opacity: 0.9, fontSize: 14, maxWidth: 480 }}>{L.subtitle}</p>
          </div>
        </div>
      </div>

      {!isMember ? (
        <LockedContent lang={lang} goTo={goTo} />
      ) : (
        <>
      {posts.length === 0 ? (
        <Card style={{ marginBottom: 18 }}>
          <p style={{ textAlign: "center", color: COLORS.muted, fontSize: 14, margin: 0 }}>{L.empty}</p>
        </Card>
      ) : (
        <Card style={{ marginBottom: 18, padding: "4px 20px", position: "relative", overflow: "hidden", background: "#FBE7EC", border: "none" }}>
          {/* wallpaper pattern */}
          <div style={{ position: "absolute", inset: 0, pointerEvents: "none", zIndex: 0 }}>
            {FORUM_PATTERN.map((it, idx) => (
              <span
                key={idx}
                style={{
                  position: "absolute", top: it.top, left: it.left, fontSize: it.size,
                  opacity: 0.15, transform: `rotate(${it.rotate}deg)`, filter: "grayscale(10%)",
                }}
              >
                {it.emoji}
              </span>
            ))}
          </div>
          <div style={{ position: "relative", zIndex: 1, padding: "16px 0 0", display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10, flexWrap: "wrap" }}>
            <span style={{ fontSize: 11, fontWeight: 800, color: COLORS.pink, textTransform: "uppercase", letterSpacing: "0.06em" }}>
              {lang === "fr" ? "Forum" : lang === "es" ? "Foro" : "Forum"}
            </span>
            {hasTranslatable && (
              <button
                type="button"
                onClick={translateAll}
                disabled={translatingAll}
                style={{
                  display: "flex", alignItems: "center", gap: 5, background: "#fff", color: COLORS.blue,
                  border: `1px solid ${COLORS.blue}44`, borderRadius: 999, padding: "5px 11px", fontSize: 10.5, fontWeight: 700,
                  cursor: translatingAll ? "default" : "pointer", opacity: translatingAll ? 0.6 : 1,
                }}
              >
                <Globe size={11} />
                {translatingAll ? L.translateAllBusy : L.translateAll}
              </button>
            )}
          </div>
          <p style={{ position: "relative", zIndex: 1, margin: "6px 0 0", fontSize: 10.5, color: COLORS.muted, fontStyle: "italic" }}>{L.translateHint}</p>
          <div style={{
            position: "relative", zIndex: 1, background: "#fff",
            borderRadius: 16, padding: "8px 18px", margin: "8px 0 16px",
            boxShadow: "0 4px 18px rgba(47,72,88,0.10)",
          }}>
          {posts.map((p, i) => {
            const avatarColors = [COLORS.pink, COLORS.sage, COLORS.blue, COLORS.ochre];
            const aColor = avatarColors[i % avatarColors.length];
            const isSeed = p.fr !== undefined; // contenu de démarrage déjà pré-traduit dans les 3 langues
            const canTranslate = !isSeed && p.origLang !== lang;
            const isTranslating = !!translatingIds[i];
            const hasTranslation = translations[i] !== undefined;
            const viewingTranslation = hasTranslation && !showOriginal[i];
            const displayText = isSeed ? p[lang] : (viewingTranslation ? translations[i] : p.text);
            return (
              <div
                key={i}
                style={{
                  display: "flex", gap: 9,
                  padding: "12px 0",
                }}
              >
                <div style={{
                  width: 26, height: 26, borderRadius: "50%", flexShrink: 0,
                  background: `linear-gradient(135deg, ${aColor} 0%, ${COLORS.teal} 130%)`,
                  color: "#fff", display: "flex", alignItems: "center", justifyContent: "center",
                  fontSize: 11, fontWeight: 700, boxShadow: "0 2px 6px rgba(47,72,88,0.15)",
                }}>
                  {p.author[0]?.toUpperCase()}
                </div>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <span style={{ fontWeight: 700, color: COLORS.teal, fontSize: 12 }}>{p.author}</span>
                  {canTranslate && (
                    <span style={{
                      marginLeft: 6, fontSize: 8.5, fontWeight: 800, color: COLORS.muted, background: COLORS.cream,
                      borderRadius: 999, padding: "1px 6px", textTransform: "uppercase", letterSpacing: "0.02em",
                    }}>{p.origLang}</span>
                  )}
                  <p style={{ margin: "3px 0 4px", fontSize: 12, color: COLORS.text, lineHeight: 1.45 }}>{displayText}</p>
                  {viewingTranslation && (
                    <p style={{ margin: "0 0 5px", fontSize: 9.5, color: COLORS.muted, fontStyle: "italic" }}>{L.translatedNote}</p>
                  )}
                  {canTranslate && (
                    <div style={{ marginBottom: 6 }}>
                      <button
                        type="button"
                        onClick={() => {
                          if (isTranslating) return;
                          if (!hasTranslation) { translateOne(i); return; }
                          setShowOriginal((prev) => ({ ...prev, [i]: !prev[i] }));
                        }}
                        style={{
                          background: "none", border: "none", padding: 0, cursor: isTranslating ? "default" : "pointer",
                          fontSize: 11, fontWeight: 700, color: COLORS.blue, textDecoration: "underline",
                        }}
                      >
                        {isTranslating ? L.translating : !hasTranslation ? L.translate : viewingTranslation ? L.seeOriginal : L.seeTranslation}
                      </button>
                      {translateErrors[i] && !isTranslating && (
                        <span style={{ marginLeft: 8, fontSize: 10.5, color: COLORS.pink }}>{L.translateError}</span>
                      )}
                    </div>
                  )}
                  <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                    <button
                      type="button"
                      onClick={() => setReaction(i, "like")}
                      style={{
                        display: "flex", alignItems: "center", gap: 5, border: "none", cursor: "pointer",
                        background: reactions[i] === "like" ? "#FDEFF3" : "rgba(255,255,255,0.6)", color: reactions[i] === "like" ? COLORS.pink : COLORS.muted,
                        borderRadius: 999, padding: "3px 9px", fontSize: 11, fontWeight: 700,
                        transition: "background 0.15s, color 0.15s",
                      }}
                    >
                      <ThumbsUp size={10} fill={reactions[i] === "like" ? COLORS.pink : "none"} />
                      {p.likes || 0}
                    </button>
                    <button
                      type="button"
                      onClick={() => setReaction(i, "dislike")}
                      style={{
                        display: "flex", alignItems: "center", gap: 5, border: "none", cursor: "pointer",
                        background: reactions[i] === "dislike" ? "#E9EEF2" : "rgba(255,255,255,0.6)", color: reactions[i] === "dislike" ? COLORS.teal : COLORS.muted,
                        borderRadius: 999, padding: "3px 9px", fontSize: 11, fontWeight: 700,
                        transition: "background 0.15s, color 0.15s",
                      }}
                    >
                      <ThumbsDown size={10} fill={reactions[i] === "dislike" ? COLORS.teal : "none"} />
                      {p.dislikes || 0}
                    </button>
                    <span
                      role="button"
                      tabIndex={0}
                      onClick={() => setOpenReplies((prev) => ({ ...prev, [i]: !prev[i] }))}
                      onKeyDown={(e) => { if (e.key === "Enter") setOpenReplies((prev) => ({ ...prev, [i]: !prev[i] })); }}
                      style={{
                        display: "flex", alignItems: "center", gap: 5, cursor: "pointer",
                        background: openReplies[i] ? COLORS.blue : "#EAF2F8", color: openReplies[i] ? "#fff" : COLORS.blue,
                        borderRadius: 999, padding: "4px 10px", fontSize: 11.5, fontWeight: 700,
                      }}
                    >
                      <Cloud size={11} fill={openReplies[i] ? "#fff" : COLORS.blue} strokeWidth={0} />
                      {L.replies((p.replies || 0) + (extraReplies[i]?.length || 0))}
                    </span>
                  </div>

                  {openReplies[i] && (
                    <div style={{ marginTop: 10, paddingLeft: 14, borderLeft: `2px solid ${COLORS.line}`, display: "flex", flexDirection: "column", gap: 8 }}>
                      {(extraReplies[i] || []).map((r, ri) => (
                        <div key={ri} style={{ fontSize: 11.5, color: COLORS.text }}>
                          <span style={{ fontWeight: 700, color: COLORS.teal }}>{r.author}</span> — {r.text}
                        </div>
                      ))}
                      <div style={{ display: "flex", gap: 6 }}>
                        <input
                          value={replyDrafts[i] || ""}
                          onChange={(e) => setReplyDrafts((prev) => ({ ...prev, [i]: e.target.value }))}
                          onKeyDown={(e) => {
                            if (e.key !== "Enter" || !replyDrafts[i]?.trim()) return;
                            setExtraReplies((prev) => ({ ...prev, [i]: [...(prev[i] || []), { author: name.trim() || (lang === "fr" ? "Anonyme" : lang === "es" ? "Anónimo" : "Anonymous"), text: replyDrafts[i].trim() }] }));
                            setReplyDrafts((prev) => ({ ...prev, [i]: "" }));
                          }}
                          placeholder={L.replyPlaceholder}
                          style={{ flex: 1, padding: "6px 9px", borderRadius: 8, border: `1px solid ${COLORS.line}`, fontSize: 11.5, fontFamily: "inherit" }}
                        />
                        <button
                          type="button"
                          onClick={() => {
                            if (!replyDrafts[i]?.trim()) return;
                            setExtraReplies((prev) => ({ ...prev, [i]: [...(prev[i] || []), { author: name.trim() || (lang === "fr" ? "Anonyme" : lang === "es" ? "Anónimo" : "Anonymous"), text: replyDrafts[i].trim() }] }));
                            setReplyDrafts((prev) => ({ ...prev, [i]: "" }));
                          }}
                          style={{ background: COLORS.teal, color: "#fff", border: "none", borderRadius: 8, padding: "6px 12px", fontSize: 11, fontWeight: 700, cursor: "pointer" }}
                        >{L.replySend}</button>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            );
          })}
          </div>
        </Card>
      )}

      <Card style={{ marginBottom: 18, padding: "10px 14px" }}>
        <div style={{ fontWeight: 800, color: COLORS.teal, marginBottom: 7, fontFamily: "Fraunces, Georgia, serif", fontSize: 12.5 }}>{L.messageLabel}</div>
        <div>
          <label style={{ ...labelStyle, marginBottom: 7 }}>{L.nameLabel}
            <input style={{ ...inputStyle, padding: "5px 8px", fontSize: 11.5 }} placeholder={L.namePlaceholder} value={name} onChange={(e) => setName(e.target.value)} />
          </label>
          <label style={{ ...labelStyle, marginBottom: 7 }}>{L.messageLabel}
            <textarea rows={2} style={{ ...inputStyle, padding: "5px 8px", fontSize: 11.5, resize: "vertical" }} placeholder={L.messagePlaceholder} value={message} onChange={(e) => setMessage(e.target.value)} />
          </label>
          <button type="button" onClick={submitPost} style={{ background: COLORS.teal, color: "#fff", border: "none", padding: "5px 13px", borderRadius: 8, fontWeight: 700, fontSize: 11, cursor: "pointer" }}>{L.post}</button>
        </div>
      </Card>

      <p style={{ fontSize: 12, color: COLORS.muted, marginTop: 12, textAlign: "center" }}>{L.demo}</p>
      </>
      )}
    </div>
  );
}

function SectionHeroCustom({ icon: Icon, color, title, desc, illuType }) {
  return (
    <div style={{
      display: "flex", alignItems: "center", justifyContent: "space-between", gap: 18, background: COLORS.card,
      border: `1px solid ${COLORS.line}`, borderRadius: 20, padding: "22px 26px",
      marginBottom: 20, boxShadow: "0 2px 14px rgba(47,72,88,0.06)",
    }}>
      <div style={{ display: "flex", alignItems: "center", gap: 18 }}>
        <div style={{ width: 62, height: 62, borderRadius: 18, background: color, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
          <Icon size={28} color="#fff" />
        </div>
        <div>
          <h2 style={{ margin: "0 0 4px", fontFamily: "Fraunces, Georgia, serif", fontSize: 23, color: COLORS.teal }}>{title}</h2>
          <p style={{ margin: 0, color: COLORS.muted, fontSize: 14.5, lineHeight: 1.5, maxWidth: 540 }}>{desc}</p>
        </div>
      </div>
      {illuType && (
        <div className="hero-illu" style={{ background: COLORS.cream, borderRadius: 16, padding: 8 }}>
          <Illustration type={illuType} size={68} />
        </div>
      )}
    </div>
  );
}

/* ---------------- WEEKLY VISUAL MENUS (Léa) ---------------- */
const MENU_DAYS = {
  fr: ["Lundi", "Mardi", "Mercredi", "Jeudi", "Vendredi", "Samedi", "Dimanche"],
  en: ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"],
  es: ["Lunes", "Martes", "Miércoles", "Jueves", "Viernes", "Sábado", "Domingo"],
};

/* ---------------- Utilitaires de semaine (rotation + dates réelles) ---------------- */
function getMondayOfCurrentWeek() {
  const now = new Date();
  const day = now.getDay(); // 0 = dimanche
  const diff = day === 0 ? -6 : 1 - day;
  const monday = new Date(now);
  monday.setDate(now.getDate() + diff);
  monday.setHours(0, 0, 0, 0);
  return monday;
}
function getISOWeekNumber(date) {
  const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
  const dayNum = d.getUTCDay() || 7;
  d.setUTCDate(d.getUTCDate() + 4 - dayNum);
  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
  return Math.ceil((((d - yearStart) / 86400000) + 1) / 7);
}
function formatShortDate(date, lang) {
  return date.toLocaleDateString(lang === "fr" ? "fr-CA" : lang === "es" ? "es-MX" : "en-CA", { day: "numeric", month: "short" });
}
function getCurrentWeekDates() {
  const monday = getMondayOfCurrentWeek();
  return Array.from({ length: 7 }, (_, i) => { const d = new Date(monday); d.setDate(monday.getDate() + i); return d; });
}
function getPregnancyInfo(dueDate, lang) {
  if (!dueDate) return null;
  const dueDateObj = new Date(dueDate + "T00:00:00");
  if (isNaN(dueDateObj.getTime())) return null;
  const conceptionStart = new Date(dueDateObj);
  conceptionStart.setDate(conceptionStart.getDate() - 280); // 40 semaines avant la DPA
  const today = new Date();
  const diffDays = Math.floor((today - conceptionStart) / 86400000);
  const weeks = Math.max(0, Math.min(42, Math.floor(diffDays / 7)));
  const days = Math.max(0, diffDays % 7);
  const trimester = weeks <= 13 ? 1 : weeks <= 27 ? 2 : 3;
  const fmtDue = dueDateObj.toLocaleDateString(lang === "fr" ? "fr-CA" : lang === "es" ? "es-MX" : "en-CA", { day: "numeric", month: "long", year: "numeric" });
  const daysRemaining = Math.max(0, Math.ceil((dueDateObj - new Date(new Date().toDateString())) / 86400000));
  return { weeks, days, trimester, fmtDue, daysRemaining };
}

